export const GLOSSARY: GlossaryEntry[] = [
  { term: "Aborted gesture of appropriation", slug: "aborted-gesture-of-appropriation", concept: "originary-scene", definitionQuote: "It is this aborted gesture of appropriation, designating the object, but no longer directed at appropriating it, that we postulate as the first sign.", definitionSource: "The Origin of Language", definitionSlug: "the-origin-of-language", posts: 23, passages: [{ text: "The aborted gesture of appropriation, then, restores that fleeting condition of perfect information in a more sustainable form.", slug: "scenic-event-intelligence", title: "Scenic/Event Intelligence", source: "Substack" }, { text: "The originary scene is a transition from the animal order governed by the Alpha to a human order governed by the center.", slug: "ga-and-the-nap", title: "Bouvard on Originary Order Versus Liberal Individualism", source: "Book" }, { text: "The originary sign, the aborted gesture of appropriation, points to a center that is simultaneously a sheer “this” (one of Wierzbicka’s primes, incidentally), that is, the very thing that we are looking at right now, and a named object and agent, from which all other names, acts and intentions derive.", slug: "on-the-use-of-the-center-margin-model-to-displace-the-left-right-model", title: "On the Use of the Center-Margin Model to Displace the Left-Right Model", source: "GABlog" }], sources: [{ slug: "clr-535", title: "The New Origin of Language: (A Derridean Parenthesis)", source: "Chronicles" }, { slug: "clr-537", title: "The New Origin of Language Part 3: The Ostensive", source: "Chronicles" }] },
  { term: "Absolute Imperative", slug: "absolute-imperative", definitionQuote: "The absolute imperative is absolute because no imperative can be issued in return by the commanded (no “God get me out of this and I’ll never…”). The absolute imperative is to stand in the place of whomever is violently centralized, i.e., scapegoated.", definitionSource: "Can Networks Crowd Out Markets?", definitionSlug: "can-networks-crowd-out-markets-gablog", posts: 20, passages: [{ text: "The absolute imperative is to stand in the place of whomever is violently centralized, i.e., scapegoated.", slug: "can-networks-crowd-out-markets-gablog", title: "Can Networks Crowd Out Markets?", source: "GABlog" }, { text: "But that in turn means that the absolute imperative is translated into the command to raise the marginal imperative.", slug: "declarative-imaginary", title: "Declarative Imaginary", source: "GABlog" }, { text: "This absolute imperative is, over time, pared down to “don’t break linguistic presence,” and this entails bringing some repetition of the originary scene in to supplement the failing linguistic presence.", slug: "programming-power-and-declarative-culture", title: "Programming, Power and Declarative Culture", source: "GABlog" }], sources: [{ slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { slug: "beyond-post-sacrificial", title: "Beyond “Post-Sacrificial”", source: "GABlog" }, { slug: "can-networks-crowd-out-markets-gablog", title: "Can Networks Crowd Out Markets?", source: "GABlog" }] },
  { term: "Abstracting", slug: "abstracting", definitionQuote: "Metaphysics aims at abstracting declarative culture from the ostensive-imperative world as completely as possible—metaphysics never comes to an end because this abstraction can never be complete: the world can never be completely described through declarative sentences that are comprised of words that can themselves be defined in declarative sentences without ever having to come to rest upon an ostensively defined word— ultimately, a name.", definitionSource: "Anthropomorphics: An Originary Grammar of the Center", definitionSlug: "anthropomorphics-book", posts: 16, passages: [{ text: "If I keep returning to and abstracting from the center, I head towards the creation of requests to the center that are simultaneously their own answers.", slug: "the-discourse-of-the-center", title: "The Discourse of the Center", source: "GABlog" }, { text: "Rather than abstracting mass organization from social interaction, the observation of social interaction itself would have to become the source of models for technological transformation.", slug: "conditions-for-an-enduring-technostructural-civilization", title: "Conditions for an Enduring Technostructural Civilization", source: "GABlog" }, { text: "They will be the source of economic dynamism, abstracting themselves and everyone else ever more thoroughly, and generating new forms of technology out of all the newly possible configurations.", slug: "absolutist-economies-gablog", title: "Absolutist Economies", source: "GABlog" }], sources: [] },
  { term: "Abstraction", slug: "abstraction", definitionQuote: "It would be better to speak of a drift towards abstraction, rather than toward arbitrariness: the sign is abstract, even the first one, which had to be normed in such a way as to supplement its self-evidence from the very beginning precisely because there was no single way of conveying the intent to cease and desist. But even in this case the abstractions we speak of are marked by the drift, by the disciplinary spaces that have constructed them: in other words, abstraction involves accentuation and abbreviation, which is necessitated by the entrance of outsiders for whom the particular version of the sign current is not self-evident while at the same time making the sign even more difficult for the next outsider to grasp.", definitionSource: "Self-Evidency", definitionSlug: "self-evidency", posts: 43, passages: [{ text: "By now, the forms of embedment defended against abstraction are the results of previous abstractions that have been re-embedded.", slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { text: "Abstraction creates new “elements,” and therefore new relations between elements.", slug: "anthropomorphics-center-and-distribution", title: "Center and Distribution", source: "Book" }, { text: "The abstraction of the sovereign from rivalry provides a model of action free from resentment: regardless of the actual motives of actual sovereigns, to the extent that they are sovereign the absence of resentment can be imputed to them.", slug: "the-generativity-of-deferral", title: "The Generativity of Deferral", source: "GABlog" }], sources: [{ slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { slug: "absolutism-the-axial-age-and-the-laboratory", title: "Absolutism, the Axial Age and the Laboratory", source: "GABlog" }] },
  { term: "Aesthetics", slug: "aesthetics", definitionQuote: "Aesthetics is located on the originary scene, in the oscillation of the attention of the participants between the sign put forth by the other and the object. The desire for the object is magnified when the participant’s attention is directed toward it by the gesture of the other; the object then attended to directly is stripped of that desirability, which then has the participant return attention to the sign.", definitionSource: "The Aesthetics of the Center", definitionSlug: "anthropomorphics-the-aesthetics-of-the-center", posts: 43, passages: [{ text: "Aesthetics is located on the originary scene, in the oscillation of the attention of the participants between the sign put forth by the other and the object.", slug: "anthropomorphics-the-aesthetics-of-the-center", title: "The Aesthetics of the Center", source: "Book" }, { text: "This history commences once aesthetics is distinguished from ritual.", slug: "the-paradoxical-telos-of-the-aesthetic-gablog", title: "The Paradoxical Telos of the Aesthetic", source: "GABlog" }, { text: "Aesthetics, then, also refuses degraded and decadent forms of sacrality, like the bizarre Christian heresies that have devolved into liberalism.", slug: "as-who-does-one-speak", title: "As Who Does One Speak?", source: "GABlog" }], sources: [{ slug: "the-paradoxical-telos-of-the-aesthetic-gablog", title: "The Paradoxical Telos of the Aesthetic", source: "GABlog" }, { slug: "the-aesthetic-as-liminally-scenic", title: "The Aesthetic as Liminally Scenic", source: "GABlog" }] },
  { term: "Agency", slug: "agency", definitionQuote: "For originary thinking, agency is deferral.", definitionSource: "Event, Origin, Center (Adam Katz)", definitionSlug: "event-origin-center", posts: 84, passages: [{ text: "Agency is located in some form of programming while the analog/screenic offers stupefaction.", slug: "programming-and-visuality-toward-inscipto-punctual-cultivation", title: "Programming and Visuality: Toward Inscipto-Punctual Cultivation", source: "Substack" }, { text: "But we will see that Lobo’s focus on the individual organism as opposed to any collective agency is an important component of his critique of the originary hypothesis.", slug: "addressing-an-objection-to-the-originary-hypthesis", title: "Addressing an Objection to the Originary Hypthesis", source: "Substack" }, { text: "The agency of the center is constructed through the ongoing interaction between center and margins.", slug: "power-and-paradox-pdf", title: "Power and Paradox (Adam Katz)", source: "Essay" }], sources: [] },
  { term: "Art", slug: "art", definitionQuote: "The scene of art is a supplement or direct replacement of the ritual scene, with the art object or happening at the center and the audience at the periphery. The art scene, then, enacts an oscillation between itself and the center, as a site of distribution and modeling of needed practices. So, all art works within, that is, imitates, and displaces some discourse on the center—ritual, myth, prayer, public discussion, interactions in the royal court or, in the modern age, the disciplines scientific, pedagogical, bureaucratic, journalistic, etc., along with privatized modes of self-regulation like diaries and letters.", definitionSource: "Puppets and Probes", definitionSlug: "puppets-and-probes", posts: 103, passages: [{ text: "The materials of art are the materials of other areas of life, which also use colors, shapes, surfaces, words, sounds, etc.", slug: "relevance", title: "Relevance", source: "GABlog" }, { text: "The scene of art is a supplement or direct replacement of the ritual scene, with the art object or happening at the center and the audience at the periphery.", slug: "puppets-and-probes", title: "Puppets and Probes", source: "GABlog" }, { text: "The separation of art from ritual coincides with the same disruption of sacral kingship that produces politics and the problem of the “tyrant.” It’s therefore not surprising that central to the first works of art is the problem of the tyrant and usurpation of the center more generally.", slug: "anthropomorphics-the-aesthetics-of-the-center", title: "The Aesthetics of the Center", source: "Book" }], sources: [{ slug: "the-aesthetic-as-liminally-scenic", title: "The Aesthetic as Liminally Scenic", source: "GABlog" }] },
  { term: "Attentional Space", slug: "attentional-space", definitionQuote: "Note that the originary hypothesis accounts for the issuing of the first sign by constructing an attentional space that is first of all convergent, and therefore dangerous, and then becomes shared—in this way, we can see attention becoming intention without anyone actually intending for this to happen.", definitionSource: "A Grammar of the Social", definitionSlug: "anthropomorphics-a-grammar-of-the-social", posts: 8, passages: [{ text: "Referring to something implicates one in an attentional space: you’re adding to the attentional “load” of something other have been, are, or might be talking about.", slug: "morality-and-reference", title: "Morality and Reference", source: "GABlog" }, { text: "The disciplinary space joins the attentional space and works on making it disciplinary by making the relation between subject and object, between those with the desires and resentments and the reality resistant to it, itself the real object of study.", slug: "order-and-repetition", title: "Order and Repetition", source: "GABlog" }, { text: "The ostensive sign, the attentional space it summons, can only be completed if supplemented by referring to what is missing in a way that would eventuate in someone supplying it.", slug: "assigning-for-interoperability", title: "Assigning for Interoperability", source: "Substack" }], sources: [] },
  { term: "Attentionality", slug: "attentionality", concept: "attentionality", definitionQuote: "I have argued previously for the priority of “attentionality” over “intentionality”—attention must precede intention, and “intention” individualizes what is “joint” in attention, making it more of a declarative than an ostensive concept.", definitionSource: "The Worlding Event", definitionSlug: "the-worlding-event", posts: 10, passages: [{ text: "This is the kind of question my essays on “attentionality” and “mistakenness” were trying to answer.", slug: "event-al-morality", title: "Event-al Morality", source: "GABlog" }, { text: "What are the new modes of attentionality; how are we seeing and giving ourselves to be seen (and heard and felt and imagined) in new ways?", slug: "selfy", title: "Selfy", source: "GABlog" }, { text: "I have argued previously for the priority of “attentionality” over “intentionality”—attention must precede intention, and “intention” individualizes what is “joint” in attention, making it more of a declarative than an ostensive concept.", slug: "the-worlding-event", title: "The Worlding Event", source: "GABlog" }], sources: [{ slug: "ap1901-1901katz", title: "Attentionality and Originary Ethics: Upclining", source: "AP Journal" }] },
  { term: "Authority", slug: "authority", definitionQuote: "The declarative sentence was always the Name of God, as we can see if we consider that to make a claim about anything is to assume that some authority would, “in the long run,” be able to authenticate that claim, even if no such authority is actually available or imaginable in any concrete way. To utter a statement is to assume you and your interlocutors will be able to continue to speak and/or act in the way licensed by that statement (to look at something, to remedy some situation, to cease some activity), i.e., to understand it; to assume that is to assume something like a guardian of the shared understanding that allows for further discourse and action, i.e., God, even if He hasn’t been named yet and in a more conventional sense never will be.", definitionSource: "The Sovereign Remembering of Names", definitionSlug: "the-sovereign-remembering-of-names", posts: 221, passages: [{ text: "That is not how moral authority is claimed; that is how it is surrendered.", slug: "obama-s-symmetries", title: "Obama’s Symmetries", source: "GABlog" }, { text: "Post-ritualistic patriarchal authority is established as a tributary of monarchical authority, which in turn models itself on the former.", slug: "fathers-and-sovereigns", title: "Fathers and Sovereigns", source: "GABlog" }, { text: "Institutional position and authority are essentially constitutive gestural elements, situating one person closer to the center or more “vertically” than another.", slug: "the-rights-of-the-anyown-2-the-idioms-of-the-anyown", title: "The Rights of the Anyown 2: The Idioms of the Anyown", source: "GABlog" }], sources: [{ slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Awe", slug: "awe", definitionQuote: "This formula goes some way toward providing an originary model for the much-celebrated awe that scientists themselves profess to feel when inquiring into the mysteries of nature: that awe is a moral experience generated by the scientist’s experience not of the object as a thing detached from human mimesis, but, on the contrary, the scientist’s sense that he or she is first in the community to experience the difference that scientific signification makes in tension with the originary sacred.", definitionSource: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Science (Part 1 of 3)", definitionSlug: "ap1202-frank1", posts: 9, passages: [], sources: [] },
  { term: "Axial Age", slug: "axial-age", definitionQuote: "The Axial Age acquisitions, then, restart history by creating centers outside of the imperial one. The Axial Age acquisitions—Greek philosophy, prophetic Judaism and Christianity and even, I think (but probably less so), Chinese philosophy, are both anti-imperial and imperial. They construct a position from which the existing emperor falls short in God’s eyes, which is to say they institute a kind of permanent resentment towards empire; while at the same time imagine an eternal and universal empire under a true, divinely ordained king.", definitionSource: "The Big Scene is the Anthropological Basis of Anarchist Ontology", definitionSlug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", posts: 39, passages: [{ text: "At the heart of the Axial Age are the antinomies of the juridical, which take the form of the possibility of an injustice beyond remedy within the justice system.", slug: "ve-ortexicality-post-axial-age-morality", title: "Ve/ortexicality: Post-Axial Age Morality", source: "Substack" }, { text: "My argument here is that the Axial Age is the ongoing testing and examination of this kind of hypothetical case which was, in fact, most closely realized in the cases of Socrates and Jesus.", slug: "the-pointman", title: "The Pointman", source: "Substack" }, { text: "The Axial Age acquisitions, then, restart history by creating centers outside of the imperial one.", slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }], sources: [{ slug: "absolutism-the-axial-age-and-the-laboratory", title: "Absolutism, the Axial Age and the Laboratory", source: "GABlog" }, { slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }] },
  { term: "Big Man", slug: "big-man", concept: "big-man", definitionQuote: "The Big Man himself emerges out of the process of imperative exchange: in the gift competition, whereby various tribal chiefs try to best each other in showing their ability to provide for the community, the Big Man is the one who so out-gifts the others that the competition is rendered moot.", definitionSource: "The Grammar of Technology", definitionSlug: "the-grammar-of-technology-gablog", posts: 127, passages: [{ text: "The Big Man is the beginning of history and of all our ethical and political dilemmas.", slug: "what-is-to-be-undone-1", title: "What is to be Undone?, 1", source: "GABlog" }, { text: "The Big Man is the Alpha, a term central to the socio-sexual hierarchy constitutive of androspheric thinking.", slug: "the-androsphere-or-the-return-of-the-big-man-who-never-really-left", title: "The Androsphere, or the Return of the Big Man (Who Never Really Left)", source: "GABlog" }, { text: "The Big Man is first of all the center of distribution: gifts come to him and he recycles them back out to the community.", slug: "the-grammar-of-technology-gablog", title: "The Grammar of Technology", source: "GABlog" }], sources: [] },
  { term: "Bureaucracy", slug: "bureaucracy", definitionQuote: "The bureaucracy, then, exists in the imperative gap: in what happens between a command being issued and that command being obeyed.", definitionSource: "War, Art, Bureaucracy and other Miscellanies", definitionSlug: "war-art-bureaucracy-and-other-miscellanies", posts: 38, passages: [{ text: "Bureaucracy is always called into being when those differences have resisted elimination, or when new, and even more egregious, differences emerge out of the wreckage of the first attempt at differencide.", slug: "toward-a-unified-field-theory-of-the-left", title: "Toward a Unified Field Theory of the Left", source: "GABlog" }, { text: "Bureaucracy is characterized by rules designed or, perhaps more often, “evolved” through settlements of specific cases, to “rationalize” interactions and regularize the functions of the institution.", slug: "continuum-of-power", title: "Continuum of Power", source: "Substack" }, { text: "Discipline and disciplines are good; bureaucracy is, if not evil, then an evil.", slug: "dismantling-the-victimocracy", title: "Dismantling the Victimocracy", source: "GABlog" }], sources: [{ slug: "the-sovereign-remembering-of-names", title: "The Sovereign Remembering of Names", source: "GABlog" }] },
  { term: "Capital", slug: "capital", concept: "capital", definitionQuote: "Modern capital is the power to abstract individuals, groups and perhaps most importantly of all, entire disciplines, from the traditions and communities within which they are embedded so as to introduce them into new hierarchies.", definitionSource: "Anthropomorphics: An Originary Grammar of the Center", definitionSlug: "anthropomorphics-book", posts: 87, passages: [{ text: "Capital is so all-embracing and all penetrating that it’s hard to imagine what it would mean to think outside of, or beyond it.", slug: "money-and-capital-as-media-and-power", title: "Money and Capital as Media and Power", source: "GABlog" }, { text: "Capital is a distribution of power aimed at solving the succession problem by constraining the possibilities—no ruler can rule against capital.", slug: "successful-succession", title: "Successful Succession", source: "GABlog" }, { text: "Capital is property that can be borrowed against and therefore generate more wealth than it contains itself—but that’s impossible if legal titles are not available, especially if much of this “property” is held not only extra-legally but illegally.", slug: "the-right-of-the-idiom-part-1", title: "The Right of the Idiom: Part 1", source: "GABlog" }], sources: [{ slug: "money-and-capital-as-media-and-power", title: "Money and Capital as Media and Power", source: "GABlog" }, { slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { slug: "power-and-capital", title: "Power and Capital", source: "GABlog" }] },
  { term: "Center", slug: "center", concept: "the-center", definitionQuote: "The center is what makes any mutual understanding (any joint attention) possible, so disclosure is aimed at interrupting concealment of the conditions of such understanding.", definitionSource: "A Kind of Apocalyptic Politics", definitionSlug: "a-kind-of-apocalyptic-politics", posts: 540, passages: [{ text: "The center is now whatever can be attended to—defined, treated, assessed, categorized, manipulated—by disciplinary metalanguages.", slug: "center-and-centrality", title: "Center and Centrality", source: "GABlog" }, { text: "The center is at the center of the totality, and yet, since the center does not belong to the totality (is not part of the totality), the totality has its center elsewhere.", slug: "anthropomorphics-the-use-of-a-center", title: "The Use of a Center", source: "Book" }, { text: "The center is what makes any mutual understanding (any joint attention) possible, so disclosure is aimed at interrupting concealment of the conditions of such understanding.", slug: "a-kind-of-apocalyptic-politics", title: "A Kind of Apocalyptic Politics", source: "GABlog" }], sources: [{ slug: "ap2402-2402katz", title: "Generative Anthropology as the One Big Discipline", source: "AP Journal" }, { slug: "clr-579", title: "The Centre", source: "Chronicles" }, { slug: "ga-as-the-thinking-of-the-center", title: "GA as the Thinking of the Center", source: "GABlog" }] },
  { term: "Centered Ordinality", slug: "centered-ordinality", definitionQuote: "We can sum this mapping of reality through social relations as “centered ordinality” (I mean no mathematical reference here): in any event , someone goes first, and being first means indicating the center around which activity will revolve, someone must go second (confirming and “standardizing” the initial gesture), third, and so on (al though I suspect that once we get past the third we will see diminishing analytical returns—we can place lots of people in the “third” category—and can just conclude the order with “last”). Centered ordinality accounts for hierarchically ordered and yet reciprocal social relations (the first must attend to the second, who is attending to the first, and so on), whether those manifested in consensually recognized pre-eminence in informal settings, or in complex and organized institutions.", definitionSource: "Language, the Deepest and Most Reliable Tradition", definitionSlug: "language-the-deepest-and-most-reliable-tradition", posts: 46, passages: [{ text: "Enacting and speaking in centered ordinality is the only way back to the center.", slug: "language-paradoxed", title: "Language Paradoxed", source: "GABlog" }, { text: "The centered ordinality you are most directly embedded in is, in its turn, embedded in another centered ordinality of which you are more or less directly aware, which your immediate center wants you to be more or less cognizant of.", slug: "anthropomorphics-the-end-of-secular-thinking", title: "The End of Secular Thinking", source: "Book" }, { text: "Centered ordinality accounts for hierarchically ordered and yet reciprocal social relations (the first must attend to the second, who is attending to the first, and so on), whether those manifested in consensually recognized pre-eminence in informal settings, or in complex and organized institutions.", slug: "language-the-deepest-and-most-reliable-tradition", title: "Language, the Deepest and Most Reliable Tradition", source: "GABlog" }], sources: [{ slug: "mistakenness-revisited-gablog", title: "Mistakenness Revisited", source: "GABlog" }, { slug: "the-architecture-of-the-center", title: "The Architecture of the Center", source: "GABlog" }] },
  { term: "Centeredness", slug: "centeredness", definitionQuote: "What makes GA, or more specifically “anthropomorphics” scientific here is that it posits, demonstrates and draws the conclusions from the inexorable centeredness of all human being.", definitionSource: "Scenic Technics", definitionSlug: "scenic-technics", posts: 12, passages: [{ text: "We’re all always and only talking about how we are deferring violence but if we don’t all always know this it is because the sign can only refer to a single center, not centeredness in general. So, in entering others’ discourse we identify those signs where reference to a single center interferes with the reference to centeredness as such. This would transform the conversation into one centered on eliciting the distinction between centering and centeredness.", slug: "gasc-2019-paper", title: "GASC 2019 Paper", source: "GABlog" }], sources: [] },
  { term: "Centering", slug: "centering", definitionQuote: "We can say, then, that centering is power. I have pointed out in previous posts (perhaps not for a while, though) that Eric Gans, in what we could call his originary history of humanity, locates the crucial turning point in the emergence of the “Big Man” who seizes the sacred center and becomes in charge of distribution.", definitionSource: "Centering", definitionSlug: "centering", posts: 56, passages: [{ text: "The means of self-centering are distributed to all of us equipped with various devices (we might say “apps”) for leveraging, mobilizing and activating those means to wind us up as proxies for various liberalizing raids.", slug: "anthropomorphics-post-sacrificial-centrality", title: "Post-Sacrificial Centrality", source: "Book" }, { text: "From my discussion of morality in “Fraud and Force,” we could say that responsible parties should establish institutions that extract from a situation in which some violent centering is possible the facts of the situation and the mode and degree of responsibility of all involved, freed from the logic of the vendetta.", slug: "moral-ethical-governance", title: "Moral, Ethical Governance", source: "GABlog" }, { text: "There are intimations of centering in even the most violent trashing.", slug: "centerism-gablog", title: "Centerism", source: "GABlog" }], sources: [{ slug: "centering", title: "Centering", source: "GABlog" }] },
  { term: "Central Authority", slug: "central-authority", definitionQuote: "There is, in any community, a central authority, the final source of imperatives; and yet those imperatives are only worthy of being followed if the central authority is in accord with the signifying center: to put I more precisely, if the imperatives issued by the central authority are the same as those issued by the signifying center.", definitionSource: "The Center and Imperative Authority", definitionSlug: "anthropomorphics-the-center-and-imperative-authority", posts: 47, passages: [{ text: "The more money in the system, the more the central authority is likely to be marketized as well.", slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { text: "In each case, some kind of resentment towards central authority is involved, ultimately for not being central and authoritative enough, as proven by the fact that one can challenge, revise and circumvent it in these very ways.", slug: "some-further-inquiry-into-hlvm-gablog", title: "Some further inquiry into HLvM", source: "GABlog" }, { text: "There is, in any community, a central authority, the final source of imperatives; and yet those imperatives are only worthy of being followed if the central authority is in accord with the signifying center: to put I more precisely, if the imperatives issued by the central authority are the same as those issued by the signifying center.", slug: "anthropomorphics-the-center-and-imperative-authority", title: "The Center and Imperative Authority", source: "Book" }], sources: [{ slug: "from-metapolitics-to-politics", title: "From Metapolitics to Politics", source: "GABlog" }, { slug: "the-event-of-technology-gablog", title: "The Event of Technology", source: "GABlog" }] },
  { term: "Central Imaginary", slug: "central-imaginary", definitionQuote: "The sovereign (more recently: central) imaginary is what you arrive at when you utter some political desire (universal healthcare, no more immigration, etc.), imagine the kind of political authority that could satisfy that desire in such a way that you could recognize it to have been satisfied, further imagine the scenic conditions that could enable the stable continuation of that authority (because you don’t want you political desire met just for a single administration) and then consider whether that authority would in fact do what you want it to do because, after all, if it could do it, it wouldn’t have to and might have something very different in mind.", definitionSource: "Language, the Ultimate Source and Analysis of Data", definitionSlug: "language-the-ultimate-source-and-analysis-of-data", posts: 8, passages: [{ text: "Once we have identified the central imaginary as the “topic” of our conversation, we can start to seek out imperatives from the center.", slug: "the-central-imaginary-gablog", title: "The Central Imaginary", source: "GABlog" }, { text: "This means we all have what we could call a “central imaginary”: a proto-narrative of the center as the agent that could meet our demands.", slug: "anthropomorphics-the-end-of-secular-thinking", title: "The End of Secular Thinking", source: "Book" }], sources: [{ slug: "the-central-imaginary-gablog", title: "The Central Imaginary", source: "GABlog" }, { slug: "the-architecture-of-the-center", title: "The Architecture of the Center", source: "GABlog" }] },
  { term: "Charismatic", slug: "charismatic", concept: "charisma", definitionQuote: "This is the point of Philip Rieff’s notion of “charisma”: the magnetic effect of a display of deferral and discipline beyond the capacity of the onlooker, in which one oscillates between exploiting the “leader”’s vulnerability and taking him as a model for engaging one’s own inner scene (an inner scene revealed for the first time through the example of the charismatic).", definitionSource: "A Kind of Apocalyptic Politics", definitionSlug: "a-kind-of-apocalyptic-politics", posts: 9, passages: [{ text: "Charismatic disclosure is therefore “apocalyptic” in the more common sense, insofar as it is always combustible, always raises hackles and induces shrieks.", slug: "a-kind-of-apocalyptic-politics", title: "A Kind of Apocalyptic Politics", source: "GABlog" }], sources: [{ slug: "beyond-post-sacrificial", title: "Beyond “Post-Sacrificial”", source: "GABlog" }] },
  { term: "Consciousness", slug: "consciousness", definitionQuote: "Human consciousness is a new awareness of others, as mediated by a sign.", definitionSource: "Salvation from the East", definitionSlug: "salvation-from-the-east", posts: 50, passages: [{ text: "First is to say that consciousness is only possible for soul or spirit.", slug: "reflections-on-reading-raymond-tallis-aping-mankind", title: "Reflections on reading Raymond Tallis, Aping Mankind", source: "GABlog" }, { text: "So consciousness is the plainest empirical fact in the world, perhaps, as Descartes observed, the only indubitable fact, the one thing we can’t doubt. There is nothing we know better.", slug: "further-reflections-consciousness-free-will", title: "Further Reflections, Consciousness & Free Will", source: "GABlog" }, { text: "In evolutionary terms, consciousness is a way for an organism to negotiate its environment.", slug: "thought-experiment", title: "Thought Experiment", source: "GABlog" }], sources: [] },
  { term: "Contemplation", slug: "contemplation", definitionQuote: "To “contemplate,” in grammatical terms, means to try out new “comments” along with the topic. These might be comments or predicates more likely to gain us access to the topic, or at least so we hope, but they might be comments or predicates that place the topic even further beyond our original desire.", definitionSource: "Declarative Imaginary", definitionSlug: "declarative-imaginary", posts: 8, passages: [{ text: "The framing effect of the sign results, according to the originary hypothesis, from the sacralization of the object through the convergence of the desires of the community; it is prerequisite not to perception itself but to the exclusive focusing of attention characteristic of esthetic contemplation.", slug: "clr-205", title: "Originary and Evolutionary Esthetics", source: "Chronicles" }, { text: "But the other is the esthetic contemplation of the linguistic sign, in which this paradoxical faith is not tested in practice but enacted, without resolution, in the imagination.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }], sources: [{ slug: "the-paradoxical-telos-of-the-aesthetic-gablog", title: "The Paradoxical Telos of the Aesthetic", source: "GABlog" }] },
  { term: "Culture", slug: "culture", definitionQuote: "Culture is a series of models of operationalization: the way we operationalize claims regarding the value of an object, is to place it on the market; if we want to operationalize a claim about nature we set up an experimental scene in which we can reduce the causal uncertainties to those we wish to study; if we want to operationalize claims about beauty we must draw the attention of others, or ourselves, in a sustained manner to the thing we find beautiful–in the inexhaustibility with which it attracts and enriches attention will lie its beauty; if we wish to operationalize claims about morality, we need to see place moral claims, or see them placed, within individual events, in some proximity to other kinds of claims and see under which conditions individuals will consider something “good’ enough to commit their honor to it; and, perhaps most difficult of all, in the sphere of law and politics, if we wish to operationalize claims about justice, right, and freedom, we must create and incessantly tend to institutions that concentrate, aggregate, display and limit power, and that can generate enclosed scenes in which abstract rules can construct the form under which we assess responsibility for events.", definitionSource: "Representation", definitionSlug: "representation", posts: 275, passages: [{ text: "The proper use of declarative culture is to articulate all this, and engage others in its articulation.", slug: "declarative-culture-properly-understood-gablog", title: "Declarative Culture, Properly Understood", source: "GABlog" }, { text: "In one sense, all of culture is originary, in the sense that all of culture can be traced back to the originary scene.", slug: "what-is-originary", title: "What is originary?", source: "GABlog" }, { text: "All of modern culture is a result of the misfit of models and aspirants, which is to say our fundamental mistakenness.", slug: "mistakenness-revisited-gablog", title: "Mistakenness Revisited", source: "GABlog" }], sources: [{ slug: "clr-648", title: "The Anthropological Idea of God—32 Years Later", source: "Chronicles" }] },
  { term: "Declarative", slug: "declarative", concept: "ostensive-imperative-declarative", definitionQuote: "The declarative was invented in the course of deferring the imperative, so it follows that one trajectory of the declarative is to imagine the abolition of the imperative.", definitionSource: "Languaging Practices", definitionSlug: "languaging-practices", posts: 240, passages: [{ text: "The declarative is born in terror of the imperative and, by extension, the ostensive, the latter of which it produces a virtual version of.", slug: "accessing-the-ostensive-within-the-declarative", title: "Accessing the Ostensive within the Declarative", source: "GABlog" }, { text: "The assumption, drawn from the originary hypothesis, that the ostensive sign is the primary linguistic form, with the imperative closely tied to the ostensive as a demand to make the indicated object present, enables us to sharpen our sense of the linguistic role of the declarative sentence.", slug: "composition-pedagogy", title: "Composition Pedagogy", source: "GABlog" }, { text: "The declarative is a kind of proposed bet that something we could recognize as the restored ostensive is out there, somewhere, and at least potentially available, if certain ostensive-imperative-ostensive conditions were to be fulfilled.", slug: "stacked-presencing", title: "Stacked Presencing", source: "Substack" }], sources: [{ slug: "on-the-proper-use-of-the-declarative-sentence", title: "On the Proper Use of the Declarative Sentence", source: "GABlog" }, { slug: "more-on-the-proper-use-of-declarative-sentences", title: "More on the Proper Use of Declarative Sentences", source: "GABlog" }, { slug: "the-declarative-order-and-inquiry", title: "The Declarative Order and Inquiry", source: "GABlog" }] },
  { term: "Declarative Culture", slug: "declarative-culture", definitionQuote: "The striving toward universal agreement is propelled by the development of declarative culture as the negation of imperative and ostensive cultures.", definitionSource: "Center and Centrality", definitionSlug: "center-and-centrality", posts: 29, passages: [{ text: "The proper use of declarative culture is to articulate all this, and engage others in its articulation.", slug: "declarative-culture-properly-understood-gablog", title: "Declarative Culture, Properly Understood", source: "GABlog" }, { text: "We are completely within ‘declarative culture” here, and declarative culture is predicated on the banishment of imperatives and ostensives that don’t “follow” from declaratives.", slug: "declarative-culture-and-imperium-in-imperio-gablog", title: "Declarative Culture and Imperium in Imperio", source: "GABlog" }, { text: "Declarative culture promises us we will only have to obey one imperative: the imperative of reality.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }], sources: [{ slug: "declarative-culture-properly-understood-gablog", title: "Declarative Culture, Properly Understood", source: "GABlog" }] },
  { term: "Desacralization", slug: "desacralization", definitionQuote: "Secularization and desacralization is ultimately de-ritualization. The myths and ideas can’t be sustained without the ritual precisely because those myths and ideas were nothing more than representations ensuring that the rituals and the community performing them could be deemed the same over time as, of course, the communities and the rituals themselves changed.", definitionSource: "Some Paradoxes", definitionSlug: "some-paradoxes", posts: 14, passages: [{ text: "Secularization and desacralization is ultimately de-ritualization.", slug: "some-paradoxes", title: "Some Paradoxes", source: "GABlog" }, { text: "A broader desacralization is necessary before “art” can take on some kind of independence relative to the sacred, but until that point aesthetic considerations would be critical to representations of the sacred.", slug: "anthropomorphics-the-aesthetics-of-the-center", title: "The Aesthetics of the Center", source: "Book" }, { text: "Here is where the not reactionary, not even conservative, but well armored, resistance to the corrosions of desacralization are to be found(ed).", slug: "breakdown", title: "Breakdown", source: "Substack" }], sources: [] },
  { term: "Description", slug: "description", definitionQuote: "Rather than drawing lines between, say description and prescription, think in terms of increasingly precise and penetrating descriptions being increasing prescriptive, while the more precise your prescription the more detailed a description is entailed. What you see, notice and articulate immediately obligates you to interfere with the world in such a way and to see, notice and articulate more, which becomes a form of data exchange.", definitionSource: "Idioms as Operationalized Samples", definitionSlug: "idioms-as-operationalized-samples", posts: 66, passages: [{ text: "I think this description is accurate and the social transformation in itself beneficial, but, as it stands, massively forgetful.", slug: "liberal-ga-reactionary-ga", title: "Liberal GA, Reactionary GA", source: "GABlog" }, { text: "We can then ask which description is better—people talking to each other as “equal” or people talking to each other as engaged in fine tuning and testing the direction each wants to lead the other.", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }, { text: "The implication of my description is that language is ordinarily invisible—we don’t notice ourselves speaking, we don’t think of ourselves as adding one word to another as we speak, much less as making sounds that we could “listen” to by bracketing their meanings.", slug: "the-right-of-the-idiom-3", title: "The Right of the Idiom, 3", source: "GABlog" }], sources: [] },
  { term: "Desire", slug: "desire", concept: "desire", definitionQuote: "Desire is generally understood in distinction from need, and in that way its specifically human quality is brought out—desire implicates us in the other, which for mimetic theory means those we imitate or, more broadly, are bound to through a web of models.", definitionSource: "Demand and the Grammar of Desire", definitionSlug: "demand-and-the-grammar-of-desire", posts: 310, passages: [{ text: "Desire is ultimately concerned, after all, not with appearance but with substance, appearance being only a means to an end.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "Desire is generally understood in distinction from need, and in that way its specifically human quality is brought out—desire implicates us in the other, which for mimetic theory means those we imitate or, more broadly, are bound to through a web of models.", slug: "demand-and-the-grammar-of-desire", title: "Demand and the Grammar of Desire", source: "Substack" }, { text: "We can certainly attribute to mimetic desire the “cause” for a particular act, but mimetic desire is always mediated through language.", slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }] },
  { term: "Disciplinarity", slug: "disciplinarity", concept: "disciplinarity", definitionQuote: "The discipline is a social form that keeps “drilling down” below ever lower thresholds of significance, and this activity applies equally to the study of quarks and of conscience.", definitionSource: "Programming, Power and Declarative Culture", definitionSlug: "programming-power-and-declarative-culture", posts: 20, passages: [{ text: "The political purpose of my study of disciplinarity is to get at the discursive roots, the roots in a habit of thinking, of “political philosophy,” in all its forms, including the most everyday, “popular” ones.", slug: "prolegomena-to-the-study-of-the-origins-of-the-disciplines-gablog", title: "Prolegomena to the Study of the Origins of the Disciplines", source: "GABlog" }, { text: "In the most basic sense, there is nothing but disciplinarity: disciplinarity is coextensive with the human: the originary scene was a discipline, even if that cannot be recognized until a critical mass of overlapping disciplines has emerged.", slug: "introduction-to-disciplinarity", title: "An Introduction to Disciplinarity (Adam Katz)", source: "Essay" }, { text: "The mode of exchange with the center of disciplinarity is that of data security, which includes the creation and archiving of knowledge that would, say, both inform a speech regime organized around a robust enforcement of laws against slander, libel and defamation while remaining invulnerable to that regime.", slug: "disciplinarity-and-the-center", title: "Disciplinarity and the Center", source: "Substack" }], sources: [] },
  { term: "Disciplinary Space", slug: "disciplinary-space", definitionQuote: "A disciplinary space is organized around a sign oscillating between predictability and novelty—a discipline like sociology comes into being because something unrecognizable had emerged in human groups, something that didn’t fit terms like “community,” “nation,” “polis,” “republic,” “people,” “kingdom,” etc. Genuine disciplinary spaces tend to take shape in the corners of the established, institutionalized ones, through “satirical” repetitions of their founding gestures and concepts.", definitionSource: "The Single Source of Moral and Intellectual Innovation", definitionSlug: "the-single-source-of-moral-and-intellectual-innovation-gablog", posts: 99, passages: [{ text: "The disciplinary space is where we argue over these questions and construct such a center, and you have a disciplinary space when enough of these decisions have been made so that those within the discipline can readily generate new questions while those outside of the discipline would essentially be guessing if they tried.", slug: "disciplining-disciplines", title: "Disciplining Disciplines", source: "GABlog" }, { text: "The disciplinary space is an engine of differentiations, turning the object into a generator of new signs.", slug: "introduction-to-disciplinarity", title: "An Introduction to Disciplinarity (Adam Katz)", source: "Essay" }, { text: "Language learning is lifelong—entering a new disciplinary space is learning a new language.", slug: "center-and-centrality", title: "Center and Centrality", source: "GABlog" }], sources: [] },
  { term: "Embedment", slug: "embedment", definitionQuote: "The traditionalist opposes abstraction in the name of full embedment, but the possibility of rejecting abstraction disappeared with the rise of divine kingship a few millennia ago. By now, the forms of embedment defended against abstraction are the results of previous abstractions that have been re-embedded.", definitionSource: "Anthropomorphics: An Originary Grammar of the Center", definitionSlug: "anthropomorphics-book", posts: 10, passages: [{ text: "By now, the forms of embedment defended against abstraction are the results of previous abstractions that have been re-embedded.", slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }], sources: [{ slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }] },
  { term: "Esthetic", slug: "esthetic", definitionQuote: "The esthetic is a postponement or deferral of sacrifice, and narrative is the exemplary esthetic form because it thematizes deferral, makes it explicit.", definitionSource: "Sacrificial Stories", definitionSlug: "clr-54", posts: 48, passages: [{ text: "The esthetic is thereby reabsorbed back into ritual and elicits the millennia long suppressed producer’s desire of all the people.", slug: "participation", title: "Participation", source: "GABlog" }, { text: "The satiric dimension within the esthetic is this moment of the scene at its most scenic, where we have what Gans once referred to as the “fearful symmetry” where each is at once potential victim and potential attacker, threatening and vulnerable simultaneously.", slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { text: "Yet no student of painting or sculpture considers the pictorial or plastic components of artworks as in themselves devoid of esthetic interest, apprehended and integrated by means of a formal “competence” to which the esthetic is irrelevant.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }], sources: [{ slug: "clr-260", title: "Originary and/or Kantian Esthetics I", source: "Chronicles" }, { slug: "clr-577", title: "Institutional Representation: The Esthetic II", source: "Chronicles" }] },
  { term: "Ethics", slug: "ethics", definitionQuote: "Ethics is concerned with creating practical models of human exchange against the background of the originary moral model of perfect reciprocity. Beyond this minimal configuration, there is no “just” or “good” society to serve ethics as a utopian model.", definitionSource: "Window of Opportunity", definitionSlug: "clr-248", posts: 84, passages: [{ text: "If ethics is centered upon some good to be obtained, morality defers another kind of centering—the violent centering involved in sacrificial practices.", slug: "crowding-out-the-political-gablog", title: "Crowding Out the Political", source: "GABlog" }, { text: "Disciplines stay alive to the extent that the tension between value and ethics is re-established, through the creation of various forms of “ skunkworks ” within disciplines.", slug: "sovereignty-and-standardization", title: "Sovereignty and Standardization", source: "GABlog" }, { text: "While it doesn’t quite prove anything, doesn’t the fact that so many millions of people can be recruited into an increasingly apocalyptic leftism that in many cases at least cuts against individual economic self-interests suggest that for many, if not most, utilitarian ethics are extremely unsatisfying?", slug: "can-networks-crowd-out-markets-gablog", title: "Can Networks Crowd Out Markets?", source: "GABlog" }], sources: [{ slug: "ap1901-1901katz", title: "Attentionality and Originary Ethics: Upclining", source: "AP Journal" }, { slug: "ap1601-1601katz", title: "Originary Mistakenness, Defilement and Modernity", source: "AP Journal" }] },
  { term: "Exemplary Victim", slug: "exemplary-victim", definitionQuote: "The exemplary victim is the one whose path we could follow as a means of salvation while always falling infinitely short of the example.", definitionSource: "Urbanomics", definitionSlug: "urbanomics", posts: 11, passages: [{ text: "The exemplary victim is the one whose path we could follow as a means of salvation while always falling infinitely short of the example.", slug: "urbanomics", title: "Urbanomics", source: "GABlog" }, { text: "The exemplary victim is constitutive of our language and narratives, which is why it needs to be “unwritten.” The whole range of exemplary victims produced across the political spectrum constitutes our “alphabet” (or, perhaps, “meme factory”).", slug: "toward-a-media-moral-synthesis", title: "Toward a Media-Moral Synthesis", source: "GABlog" }, { text: "A large part of the power of models figuring an “exemplary victim” is precisely the plausibility and richness of the events they are drawn from, with Jesus on the cross, or Socrates sitting with his students waiting to drink his hemlock among the most obvious examples.", slug: "the-model-of-data", title: "The Model of Data", source: "GABlog" }], sources: [{ slug: "toward-a-media-moral-synthesis", title: "Toward a Media-Moral Synthesis", source: "GABlog" }, { slug: "dialectics", title: "Dialectics", source: "GABlog" }] },
  { term: "Explanation", slug: "explanation", definitionQuote: "But if the sacred is identical to the significant, then any explanation is, knowingly or not, simply further inquiry into and commentary on the sacred center, and hence dependent on it.", definitionSource: "Bouvard on Sacred Ritual Beyond Explanation", definitionSlug: "what-is-your-stance-on-hobbes-leviathan", posts: 67, passages: [{ text: "And the libertarian explanation is… well, other than some vague references to our having forgotten our principles, it doesn’t seem to me they really have one—which would be why someone like Ron Paul exceeds even the most fevered Leftists in his conspiracy-mongering.", slug: "the-political-economy-of-freedom-and-sovereignty", title: "The Political Economy of Freedom and Sovereignty", source: "GABlog" }, { text: "It seems to me that the best explanation is the alliance of the new, vulnerable, but potentially revolutionary market order with the absolutist state—the imperial state, in other words, which is really nothing more than a permanently asymmetrical gift relationship (is there anything more “given” for us today than the state?).", slug: "the-terror-of-the-given", title: "The Terror of the Given", source: "GABlog" }, { text: "“Explains” lets us know more implicitly that an explanation is coming.", slug: "writing-pedagogy-katz", title: "From Novice to Apprentice: A Pedagogy of \"Academic Discourse\" (Adam Katz)", source: "Essay" }], sources: [] },
  { term: "Firstness", slug: "firstness", concept: "firstness", definitionQuote: "It is to the freedom that made the sign possible in the first place, and that permits its use to transcend the symmetry of the communal sharing of meaning that makes human existence possible, that I have given the name of firstness , in order to emphasize the impossibility of avoiding priority even in the most utopian vision of the human community. It is essential to point out that the exchange of signs, and similar cultural acts, are the only ones that permit the seamless adoption of an individual’s innovation by the entire community, and that it is precisely this possibility of firstness that makes it the foundation of the human community.", definitionSource: "Toward a Globalist-Victimary Unified Field Theory: Part V – A Morality of Firstness", definitionSlug: "clr-603", posts: 55, passages: [{ text: "Maybe that will happen, if firstness is ever restored through a generalized immunity to the victimary.", slug: "the-androsphere-or-the-return-of-the-big-man-who-never-really-left", title: "The Androsphere, or the Return of the Big Man (Who Never Really Left)", source: "GABlog" }, { text: "A reliable indicator of firstness is the ability to revise previous assessments and assignments and to formalize present fitness.", slug: "mimetic-theory-and-high-low-v-the-middle", title: "Mimetic Theory and High-Low v the Middle", source: "GABlog" }, { text: "Second, though, as I suggested earlier, Jewish firstness is represented by a willingness to endure historical contingency, adhere to the moral law (even if no one else does), and ask for no recognition or “proof” of election.", slug: "anti-semitism", title: "Anti-Semitism", source: "GABlog" }], sources: [{ slug: "clr-606", title: "Sovereignty and Firstness", source: "Chronicles" }, { slug: "clr-451", title: "Reciprocity and Firstness", source: "Chronicles" }, { slug: "clr-496", title: "Religion and Firstness", source: "Chronicles" }] },
  { term: "Frame", slug: "frame", definitionQuote: "To frame is to rule, and to target ways to enhance discipline is to frame.", definitionSource: "Frame, Symmetry, Equality", definitionSlug: "frame-symmetry-equality", posts: 167, passages: [{ text: "If your frame is wrong, that’s the only way you’ll ever find out anyway.", slug: "within-language", title: "Within Language", source: "GABlog" }, { text: "To frame is to rule, and to target ways to enhance discipline is to frame.", slug: "frame-symmetry-equality", title: "Frame, Symmetry, Equality", source: "GABlog" }, { text: "What makes it that kind of frame is the practice that initiated it, and the way it draws in the elements and means from the whole.", slug: "truth-and-practice", title: "Truth and Practice", source: "GABlog" }], sources: [] },
  { term: "Framing", slug: "framing", definitionQuote: "So, framing is ruling and framing is playing. It’s ruling for the one who is both inside and outside the game, and being both inside and outside of the game is itself a form of discipline—being outside of the game you participate in is possible insofar as you know that the positions and moves in the game are ways of framing and channeling resentments that have their origins elsewhere and must be staged and unfolded in an orderly manner in order to be reconciled to reality.", definitionSource: "Frame, Symmetry, Equality", definitionSlug: "frame-symmetry-equality", posts: 82, passages: [{ text: "Everyone must speak for the same amount of time?), the deliberative process is impaired, and if that framing is encouraged, it will impair the process beyond repair.", slug: "equality-and-morality-gablog", title: "Equality and Morality", source: "GABlog" }, { text: "In other words, power judges us in terms of “equality” or “duty.” The best framing is the one that unites power and accountability, that gives everyone the power to do what they are obliged to do—in other words, absolutist framing.", slug: "sovereign-resentments", title: "Sovereign Resentments", source: "GABlog" }, { text: "Every one of us does know things about our respective milieus that no one else does, even if it may sometimes be the case that the proper questioning or framing is required to elicit such knowledge.", slug: "mimesis-center-auto-immunology", title: "Mimesis, the Center and Auto-Immunology: A Review of Psychopolitical Anaphylaxis", source: "Essay" }], sources: [] },
  { term: "Free will", slug: "free-will", definitionQuote: "The real question of free will refers to our responsibility for our acts, and the moral notion of responsibility, which derives fairly directly from the moral model instituted at the originary event, is itself a highly determining factor (what Freud called the superego ) in our behavior.", definitionSource: "Nim and Nothingness", definitionSlug: "clr-423", posts: 14, passages: [{ text: "On the other hand, consciousness and free will are completely anomalous in our universe.", slug: "further-reflections-consciousness-free-will", title: "Further Reflections, Consciousness & Free Will", source: "GABlog" }, { text: "Saying that human consciousness and free will are a function of our unique cultural/social “nature” may well be true, but it doesn’t seem to answer the philosophical problem of how exactly this is possible.", slug: "reflections-on-reading-raymond-tallis-aping-mankind", title: "Reflections on reading Raymond Tallis, Aping Mankind", source: "GABlog" }, { text: "But this is not an act of existential free will on the part of each member of the new community.", slug: "anthropomorphics-origin-and-hypothesis", title: "Origin and Hypothesis", source: "Book" }], sources: [] },
  { term: "Freedom", slug: "freedom", definitionQuote: "Freedom is whatever you can do within and with the rules. Rules emerge in any space where violence has been sufficiently deferred so that it can be kept out of mind, and they are as thick (exclusive and prescriptive) as they need to be in order to keep it out of mind.", definitionSource: "The Mistake of Liberal Democracy", definitionSlug: "the-mistake-of-liberal-democracy", posts: 183, passages: [{ text: "The notion that equality and freedom are competing values is false to the core.", slug: "the-mistake-of-liberal-democracy", title: "The Mistake of Liberal Democracy", source: "GABlog" }, { text: "The elemental form of freedom is that of the discipline: a shared, inviolate and inexhaustible locus of attention.", slug: "the-right-of-the-idiom-2", title: "The Right of the Idiom, 2", source: "GABlog" }, { text: "If the choice between freedom and coercion is thus treated as a matter of expediency, freedom is bound to be sacrificed in almost every instance.", slug: "common-sense", title: "Common Sense", source: "GABlog" }], sources: [{ slug: "the-political-economy-of-freedom-and-sovereignty", title: "The Political Economy of Freedom and Sovereignty", source: "GABlog" }, { slug: "clr-348", title: "The Four Freedoms", source: "Chronicles" }] },
  { term: "Grammatical Stack", slug: "grammatical-stack", definitionQuote: "I’m going to follow up here on the notion of the “grammatical stack,” or the imperative to “line up” the speech forms (ostensive>imperative>interrogative>declarative>imperative>ostensive) so as to approximate maximum internal referentiality across the speech forms.", definitionSource: "Stacking Against the Big Scene", definitionSlug: "stacking-against-the-big-scene", posts: 8, passages: [{ text: "To input the miraculous to the grammatical stack is to hypothesize wildly from the slightest sample.", slug: "the-algorithm-as-originary-stack", title: "The Algorithm as Originary Stack", source: "Substack" }, { text: "This involves ordering what we might call the “grammatical stack”: the articulation of ostensive-imperative-interrogative-declarative.", slug: "conversivity", title: "Conversivity", source: "GABlog" }, { text: "Full exploitation or “optimization” of the grammatical stack would lead us to ask what would be the inappropriate ostensive that initiates the technological move and what would be the inappropriate technologized imperative that integrates technology into the declarative, which is to say, juridical and disciplinary, order.", slug: "the-grammar-of-technology-substack", title: "The Grammar of Technology", source: "Substack" }], sources: [{ slug: "conversivity", title: "Conversivity", source: "GABlog" }, { slug: "deriving-the-sample-to-its-source", title: "Deriving the Sample to its Source", source: "GABlog" }] },
  { term: "Identity", slug: "identity", definitionQuote: "Identities will take on names, but more fundamentally the notion refers here to style, figuration, and idiom. Your maintenance of an identity, given to as much as taken by you, is the way you know things and make things known to others.", definitionSource: "As Who Does One Speak?", definitionSlug: "as-who-does-one-speak", posts: 87, passages: [{ text: "If the difference between the two is reduced to the infinitesimal, the two will be changing positions, so your identity is simultaneously that of a learner as well as teacher.", slug: "as-who-does-one-speak", title: "As Who Does One Speak?", source: "GABlog" }, { text: "Insofar as we have a new center, that center wants to be more central: if we have a center we are using the same sign, and its identity is affirmed in the self-reference that situates one scene generated by the sign in a history of scenes with an origin that is continually marked.", slug: "gasc-2019-paper", title: "GASC 2019 Paper", source: "GABlog" }, { text: "But we can’t do without sovereignty—it meets some very definite human needs, and is, in fact, what people usually mean when they speak about “human nature.” Sovereignty provides identity, which is first of all self-sovereignty, and, again, is inimical to freedom, as identity is just another set of shackles.", slug: "the-political-economy-of-freedom-and-sovereignty", title: "The Political Economy of Freedom and Sovereignty", source: "GABlog" }], sources: [{ slug: "identities", title: "Identities", source: "GABlog" }] },
  { term: "Imperative", slug: "imperative", concept: "ostensive-imperative-declarative", definitionQuote: "The assumption, drawn from the originary hypothesis, that the ostensive sign is the primary linguistic form, with the imperative closely tied to the ostensive as a demand to make the indicated object present, enables us to sharpen our sense of the linguistic role of the declarative sentence.", definitionSource: "Composition Pedagogy", definitionSlug: "composition-pedagogy", posts: 354, passages: [{ text: "The imperative is dependent on extra-linguistic real time in a way the ostensive is not.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "The imperative is a set of expectations: be ready for what will happen to the main opponent/watch what the president will do next/look for that oppositional leader’s profile to be raised.", slug: "programming-power-and-declarative-culture", title: "Programming, Power and Declarative Culture", source: "GABlog" }, { text: "The imperative is a result of an “inappropriate ostensive.” One member of the community issues the ostensive sign in the absence of the object, and another member of the community then supplies the object.", slug: "anthropomorphics-a-grammar-of-the-social", title: "A Grammar of the Social", source: "Book" }], sources: [] },
  { term: "Imperative Culture", slug: "imperative-culture", definitionQuote: "This progressive relation to the center is what I have been calling “imperative culture,” or the “imperative order,” or “imperativity.” The center issues commands, commands with their origins in the injunction to suspend appropriation of the object on the originary scene; the participants on any cultural scene make requests of the center.", definitionSource: "The Architecture of the Center", definitionSlug: "the-architecture-of-the-center", posts: 8, passages: [{ text: "What emerges within this imperative culture is a continual attempt to reduce the difference between performance and effect.", slug: "anthropomorphics-the-center-and-the-declarative", title: "The Center and the Declarative", source: "Book" }, { text: "In his analysis of imperative culture, Gans notes that the memory of the sacred object must conceive of that object as a sacred being that exists above and beyond the concrete manifestations it may take on.", slug: "power-and-paradox-pdf", title: "Power and Paradox (Adam Katz)", source: "Essay" }], sources: [{ slug: "the-architecture-of-the-center", title: "The Architecture of the Center", source: "GABlog" }] },
  { term: "Imperative Exchange", slug: "imperative-exchange", definitionQuote: "Our most fundamental orientation to the world is one of what we could call an “imperative exchange,” best represented by prayer: I will do what you (or, really “Thou”) instruct me, and Thou will in turn… well, the instructions we give in trying to strike a deal with God vary quite a bit, but even the atheists among us think in terms of following rule (imperative) X so that others will follow rule (imperative) Y.", definitionSource: "Sovereign Commands, Anarchistic Demands", definitionSlug: "sovereign-commands-anarchistic-demands-gablog", posts: 51, passages: [{ text: "The imperative exchange is replaced by a declarative culture in which the voice issuing the absolute imperative is always in dialogue with you to the extent that you defer the immediate imperatives to sacrifice either the target of your resentment or some proxy.", slug: "anthropomorphics-and-reaction", title: "Anthropomorphics and Reaction", source: "GABlog" }, { text: "The imperative exchange is embedded in a sacrificial economy: the subject demands more and more of God, as each form of salvation brings another form into view, and so God correspondingly demands more in return: in the end, the most treasured possession, i.e., your first born.", slug: "the-sovereign-remembering-of-names", title: "The Sovereign Remembering of Names", source: "GABlog" }, { text: "Imperative exchange is ancestor worship, and the absolute imperative embedded in I AM THAT I AM is to suspend ancestor worship and remember the originary scene—that is, remember that it is the participation of all in creating reciprocity that generated the sign, not the other way around.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }], sources: [{ slug: "beyond-post-sacrificial", title: "Beyond “Post-Sacrificial”", source: "GABlog" }] },
  { term: "Imperative Gap", slug: "imperative-gap", definitionQuote: "There is always an “imperative gap” between the command issued and the command obeyed—no order can be obeyed without at least some degree of discretion being exercised. The practice of commanding is both to minimize this gap and to fill it with preceding exemplars, previous decisions, and previous exercises of discretion which can be translated for current purposes, along with an entire sensory and investigatory apparatus to follow up on and therefore inform obedience to the imperative.", definitionSource: "The Imperative of the Occupant of the Center", definitionSlug: "the-imperative-of-the-occupant-of-the-center", posts: 27, passages: [{ text: "The work of closing the imperative gap is conducted in “disciplinary spaces,” which are retrievals of the originary scene/event.", slug: "scale", title: "Scale", source: "Substack" }, { text: "Now, I can say that the imperative gap is closed to the extent that each of us contributes to singularized succession in perpetuity.", slug: "the-sufficiency-of-singularized-succession-in-perpetuity", title: "The Sufficiency of Singularized Succession in Perpetuity", source: "Substack" }, { text: "One’s operationalization of the imperative gap is not an individual matter but derivative of one’s position within the stack of scenes—you can only start with the commands it is within your power to work with, and with whatever clarity the chain of imperatives they issue from is inscribed upon those aimed at you.", slug: "the-problem-of-obedience-revisited", title: "The Problem of Obedience, Revisited", source: "Substack" }], sources: [{ slug: "the-imperative-of-the-occupant-of-the-center", title: "The Imperative of the Occupant of the Center", source: "GABlog" }, { slug: "the-model-of-data", title: "The Model of Data", source: "GABlog" }] },
  { term: "Imperative of the Center", slug: "imperative-of-the-center", definitionQuote: "The need for maintaining or restoring presence itself derives from the originary scene—we can say, a little anachronistically, that preserving linguistic presence is the first imperative of the center. And what it meant first of all was that each member on the scene ensure that his sign was the same as that issued by others.", definitionSource: "Praxis", definitionSlug: "praxis", posts: 17, passages: [{ text: "The problem of access to the imperative of the center is the problem of institution building, of data security and scenic design practices.", slug: "muffled-transmission-from-the-center-substack", title: "Muffled Transmission from the Center", source: "Substack" }, { text: "The parceling out of the imperative of the center means that a calculated strategy of betting against those most dedicated to the creation and transmission of practices of data security can not only break those lines of transmission but can turn those very practices against them.", slug: "modeling-thirdness-2", title: "Modeling Thirdness 2", source: "Substack" }, { text: "What I have been calling the partitioning and parceling out of the imperative of the center is not so much resisted as raveled up by creating knowledge of use to cases in stacked scenes that keeps pushing cases asymptotically to their self-abolishing limits.", slug: "the-same-sentence", title: "The Same Sentence", source: "Substack" }], sources: [{ slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }, { slug: "the-imperative-constant", title: "The Imperative Constant", source: "GABlog" }] },
  { term: "Imperativity", slug: "imperativity", definitionQuote: "This progressive relation to the center is what I have been calling “imperative culture,” or the “imperative order,” or “imperativity.” The center issues commands, commands with their origins in the injunction to suspend appropriation of the object on the originary scene; the participants on any cultural scene make requests of the center.", definitionSource: "The Architecture of the Center", definitionSlug: "the-architecture-of-the-center", posts: 16, passages: [{ text: "Within interrogative imperativity, declaratives take on a far wider scope, that of converting possible (and impossible) imperative exchanges into a rule or constraint for deferring “analogous” imperative exchanges.", slug: "beyond-post-sacrificial", title: "Beyond “Post-Sacrificial”", source: "GABlog" }, { text: "The para and the infra are the forms of imperativity, telling you what texts you must take as models, how to take them as models, how to use those models to work through some particular content or materials, and how to read texts as instantiations or modifications of those models.", slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }], sources: [{ slug: "the-architecture-of-the-center", title: "The Architecture of the Center", source: "GABlog" }, { slug: "imperativity", title: "Imperativity", source: "GABlog" }] },
  { term: "Individualism", slug: "individualism", definitionQuote: "Don’t look at me as a “_____,” the individual demands, look at me as… the other of “_____.” Individualism is a kind of negative gnostic theology. David Graeber’s discussion in Debt: the First 5,000 Years emphasizes the violence intrinsic to this abstraction of individuals from their dependencies.", definitionSource: "Sovereign as Onomastician-in-Chief", definitionSlug: "sovereign-as-onomastician-in-chief", posts: 17, passages: [{ text: "Don’t look at me as a “_____,” the individual demands, look at me as… the other of “_____.” Individualism is a kind of negative gnostic theology.", slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }, { text: "There can never be enough democracy, freedom, individualism, peace, tolerance—the concepts, unlike, say, sovereignty , are intrinsically open-ended and even infinite.", slug: "trump-s-process-of-inquiry-gablog", title: "Trump’s Process of Inquiry", source: "GABlog" }, { text: "The most terrible consequences of liberal individualism come from the destruction of this assumption that all individuals, before all else, have their entire existence within the group.", slug: "distribution-from-the-center", title: "Distribution from the Center", source: "GABlog" }], sources: [] },
  { term: "Inquiry", slug: "inquiry", definitionQuote: "Inquiry is a act of marking and unmarking—when we are converging on the object, the object is marked for destruction, but once the sign is issued we attend, first, from the sign to the object, unmarking the formal sign and sharing our marking of the object; and then, second, we attend from the object to each other, thereby unmarking the object (which is to say unmarking everyone’s defense of, resentment on behalf of, the object) and marking our own now evident, because naked, desire for the object and resentment toward the others.", definitionSource: "A Sapir-Katz Hypothesis", definitionSlug: "a-sapir-katz-hypothesis", posts: 273, passages: [{ text: "The inquiry into resentment, which is always the resentment of specific selves and others, is presumably part of culture, so this inquiry is itself part of the impossible attempt to represent and defer its own resentment.", slug: "resentment", title: "Resentment", source: "Substack" }, { text: "Inquiry is required to invent and regulate that technological mechanism, but once it is controlled by the feedback from measurable effects (the regularized relation between laughter and ratings) not only has the discipline of comedy been displaced but so, also, has the disciplinary inquiry into various forms of inducing laughter.", slug: "introduction-to-disciplinarity", title: "An Introduction to Disciplinarity (Adam Katz)", source: "Essay" }, { text: "The new pedagogy or mode of inquiry is then, partly explicitly and partly tacitly, integrated into the system of reciprocities.", slug: "sovereignty-difference-reciprocity-nature-value", title: "Sovereignty, Difference, Reciprocity, Nature, Value", source: "GABlog" }], sources: [] },
  { term: "Intentionality", slug: "intentionality", definitionQuote: "Intentionality is not simply will, but the will to produce a certain effect, not out of “instinct” but as an at least potentially thematized reality.", definitionSource: "On Providence", definitionSlug: "clr-780", posts: 45, passages: [{ text: "Each layer of intentionality is a layer of deferral, and being able to say that maybe we can know or see allows us to add more layers.", slug: "toward-a-generative-logic-of-translation", title: "Toward a Generative Logic of Translation", source: "GABlog" }, { text: "Built into the notion of intentionality is some deep structure of the will; built into the notion of attention is something demanding attention and demanding you draw others’ draw others’ attention to, which involves configurating ourselves around something at the center.", slug: "the-center", title: "Lecture 4: The Center", source: "Essay" }, { text: "This presence is a collective, centered presence, and not the phenomenological self-presence (in which my intentionality is fully “borne” by my utterances) Derrida deconstructs, but a presence nevertheless.", slug: "the-name-of-god-technomedia-and-the-model-of-the-work-of-art", title: "The Name of God, Technomedia, and the Model of the Work of Art", source: "GABlog" }], sources: [] },
  { term: "Internal Scene of Representation", slug: "internal-scene-of-representation", definitionQuote: "One’s internal scene of representation is the mental space within which we conceive the meaning of language, as when listening to another or reading a book. Such an individual space, however implemented in our nervous system, must have begun to exist in the originary event itself, or in any case in the memory of those who had participated in the event and its early repetitions.", definitionSource: "The Origin of Language", definitionSlug: "the-origin-of-language", posts: 10, passages: [{ text: "One’s internal scene of representation is the mental space within which we conceive the meaning of language, as when listening to another or reading a book.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "If we are to speak of an internal scene of representation, it must be composed as any scene—by means of a sign of deferral of some appropriation that would, if attempted, destroy the scene.", slug: "psychogeography", title: "Psychogeography", source: "GABlog" }, { text: "This renunciation of the temptation to occupy internal scene of representation in rebellion against the tyrant in the name of some super-sovereign is what we can call “donating your resentment to the center.” Media and technology are, as Marshall McLuhan noted, extensions of our senses and body.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }], sources: [{ slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { slug: "clr-531", title: "Paradox and the Sacred", source: "Chronicles" }] },
  { term: "Interrogative", slug: "interrogative", concept: "ostensive-imperative-declarative", definitionQuote: "Intervening between the imperative and the declarative is the interrogative; an interrogative is a softened imperative, which is to say, an imperative coming to recognize that it might not be fulfilled, and therefore transitioning from a command to do something to a demand for information regarding the possibility of doing it.", definitionSource: "More on the Proper Use of Declarative Sentences", definitionSlug: "more-on-the-proper-use-of-declarative-sentences", posts: 80, passages: [{ text: "The interrogative is a prolonged imperative, which is to say an imperative that understands it may not be obeyed.", slug: "the-grammar-of-desire-and-resentment", title: "The Grammar of Desire and Resentment", source: "GABlog" }, { text: "The assumption, drawn from the originary hypothesis, that the ostensive sign is the primary linguistic form, with the imperative closely tied to the ostensive as a demand to make the indicated object present, enables us to sharpen our sense of the linguistic role of the declarative sentence.", slug: "composition-pedagogy", title: "Composition Pedagogy", source: "GABlog" }, { text: "And then we become ostensive, imperative, interrogative and declarative signs of the center.", slug: "total-semiotics-or-exteriorizing-the-interiors", title: "Total Semiotics, or Exteriorizing the Interiors", source: "GABlog" }], sources: [] },
  { term: "Justice", slug: "justice", concept: "justice", definitionQuote: "The assumption, though, is still that distribution comes from the center: justice is the distribution to each of his due, whatever that means and however it is to be determined.", definitionSource: "Distribution from the Center", definitionSlug: "distribution-from-the-center", posts: 170, passages: [{ text: "The imperial institution of justice is therefore quite hostile to the heads and chiefs and the extended kinship relations they embody.", slug: "on-the-juridical-disciplinary-line", title: "On the Juridical/Disciplinary Line", source: "Substack" }, { text: "The only way to provide sovereignty with an appropriate form of justice is to give discursive articulation to the difference between power applied so as to preserve the social order and power applied in obedience to a power greater than the sovereign.", slug: "centrality-power-sovereignty", title: "Centrality, Power, Sovereignty", source: "GABlog" }, { text: "That threshold itself is assessed with the specific networks in mind—even vigilante justice is not necessarily excluded, as long as it doesn’t pass the threshold beyond which there will be nothing but vigilante justice.", slug: "constrained-economies", title: "Constrained Economies", source: "GABlog" }], sources: [{ slug: "distribution-from-the-center", title: "Distribution from the Center", source: "GABlog" }, { slug: "clr-665", title: "Originary Reflections on the Present", source: "Chronicles" }] },
  { term: "Law", slug: "law", definitionQuote: "Needless to say, every law is enforced (or left unenforced) by someone. What the “rule of law” really means is that power has no final destination. For every person who can enforce the laws with regards to others, there’s someone who can enforce the law upon him.", definitionSource: "Sovereignty Heisenbergian and Godelian", definitionSlug: "sovereignty-heisenbergian-and-godelian", posts: 265, passages: [{ text: "The law is sufficient, that is, to continually generate hypotheses of the law’s emergence and revised terms of its evolution, to maintain its divine sanction while reducing that sanction to maintaining the collegiality and accountability of its interpreters and the inexhaustibility of the shared text.", slug: "why-the-law-is-enough", title: "Why the Law is Enough", source: "GABlog" }, { text: "Generally honor cultures exist where the rule of law is weak.", slug: "up-from-victimhood", title: "Up from Victimhood", source: "GABlog" }, { text: "Needless to say, every law is enforced (or left unenforced) by someone.", slug: "sovereignty-heisenbergian-and-godelian", title: "Sovereignty Heisenbergian and Godelian", source: "GABlog" }], sources: [] },
  { term: "Legitimacy", slug: "legitimacy", definitionQuote: "Now we can speak of something equivalent to “legitimacy,” or the intrinsic relation between ostensive and imperative, as residing in the more specific origin of any community. The communist or liberal or revolutionary or usurpationist origin of the country where you find your obligations, then, cannot be “illegitimate.”", definitionSource: "Center and Origin: The Name-of-the-Center and Centered Names", definitionSlug: "center-and-origin-the-name-of-the-center-and-centered-names", posts: 99, passages: [{ text: "If indeed my continued Fukuyama-like assertion of the superiority of liberal democracy is correct, then there is no “higher” argument for one side or the other; the very existence of two matched parties suggests that they have equal legitimacy and that that legitimacy is itself the highest political value. The seemingly hypocritical condition of political debate in which the sides contest each other’s legitimacy on an intellectual level while accepting it on a procedural level is the paradoxical foundation of liberal democracy.", slug: "clr-424", title: "A GA Criterion of Social Health", source: "Chronicles" }, { text: "History, then, has exhausted itself in the antinomic agencies of contemporary liberalism, where the genuinely stripped bare human that can be the only source of legitimacy is nothing but sheer opposition to whatever norms make social functioning possible.", slug: "anthropomorphics-declarative-order-and-the-center", title: "Declarative Order and the Center", source: "Book" }, { text: "But what does the increasing or more intractable inequality have to do with the diminishing legitimacy function of the welfare state—is it that the rich no longer have enough money to support it or the less able are no longer willing to accept the bribe (or have figured out that the bribe will continue even if legitimacy is denied)?", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }, { text: "Success is only possible if you turn the infiltrators into your tools: speak always and only as if you will only obey the commands of legitimate leaders of legitimate institutions, and you are always simply pointing out that the rate of turnover in terms of legitimacy is accelerating and it can be rather difficult to keep up.", slug: "event-origin-center", title: "Event, Origin, Center (Adam Katz)", source: "Essay" }], sources: [{ slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Linguistic Presence", slug: "linguistic-presence", definitionQuote: "There is a term that Gans uses throughout The Origin of Language that I think can be translated directly into “sustain the center”: “linguistic presence.” Maintaining linguistic presence is the urgent imperative that takes us through the succession of speech acts, from the ostensive, through the imperative and to the declarative. At each point a potential break in linguistic presence, which always means a potential outbreak of violence, is what forces the transition from one speech form to another.", definitionSource: "Semiotic Engineering", definitionSlug: "semiotic-engineering-gablog", posts: 53, passages: [{ text: "Linguistic presence is not a “channel” of communication, and al though for the higher linguistic forms, the channel analogy is an adequate approximation in most cases, it cannot help us to understand the origin of these forms.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "The problem of linguistic presence is now posed in a new way.", slug: "anthropomorphics-a-grammar-of-the-social", title: "A Grammar of the Social", source: "Book" }, { text: "If the other disobeys, linguistic presence is put in danger, and the moral thing to do is find some other way of maintaining it.", slug: "moral-thresholds", title: "Moral Thresholds", source: "GABlog" }], sources: [{ slug: "deriving-the-sample-to-its-source", title: "Deriving the Sample to its Source", source: "GABlog" }, { slug: "sampling-on-the-data-exchange", title: "Sampling on the Data Exchange", source: "Substack" }] },
  { term: "Linguistic Turn", slug: "linguistic-turn", definitionQuote: "Gans' originary hypothesis completes the \"linguistic turn\" of 20th century thought—the intuition guiding the dismantling of metaphysics by 20th century thinkers was that language doesn't represent some external and independent reality; on the contrary, language, or more generally, signs, is constitutive of anything we can call a human reality. What Gans' hypothesis does is explain why language is constitutive: because it was through the sign that our immediate ancestors transcended the mimetic rivalry that perpetually threatened their existence by discovering/inventing a way of deferring violence.", definitionSource: "Another Version of \"Idioms of Inquiry\" Despite the Changed Title (Adam Katz)", definitionSlug: "idioms-of-inquiry-katz", posts: 12, passages: [{ text: "The reason for the linguistic turn is that the metaphysical scene of humanism, predicated upon the metalinguistics of literacy, could no longer effectively defer violence.", slug: "gasc-2019-paper", title: "GASC 2019 Paper", source: "GABlog" }, { text: "Completing the linguistic turn is essential because the metalanguages of humanism and metaphysics obscure the forms of authority needed to ensure intelligent participation in institutions and hierarchical orders.", slug: "linguistic-turn-generative-literacy", title: "The Linguistic Turn and Generative Literacy (Adam Katz)", source: "Essay" }, { text: "The linguistic turn in Western thought in the 20 th century derives from this recognition, which was certainly aided by both the emergence of mass literacy and mass education, and by the emergence of new media that made it possible to place writing in a broader historical context.", slug: "within-language", title: "Within Language", source: "GABlog" }], sources: [{ slug: "gasc-2019-paper", title: "GASC 2019 Paper", source: "GABlog" }] },
  { term: "Literacy", slug: "literacy", definitionQuote: "literacy is invented so as to refer to realm of the implicit in framing the speech of others. This reduces the intensity of imitation and allows for the emergence of a space of de-escalated imitation that we can pretend isn’t imitation at all.", definitionSource: "Exhaustive Imitation", definitionSlug: "exhaustive-imitation", posts: 116, passages: [{ text: "Literacy is crucially involved in the shift in the heroic narrative from the “Promethean” (and doomed) struggle against the center to the victim who exemplifies what we can now see as the unholy, even Satanic, violence of the imperial center.", slug: "toward-a-media-moral-synthesis", title: "Toward a Media-Moral Synthesis", source: "GABlog" }, { text: "For this purpose the metalanguage of literacy is deployed: relations between nominalizations deposit in the scene what might otherwise be looked for in the disciplinary scene of representation.", slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }, { text: "The metalanguage of literacy is an intellectual or ideological bulwark to the state, while also providing the material for decentering power by appealing to transcendent models to which the sovereign must adhere.", slug: "linguistically-constructed-empires-within-empires", title: "Linguistically Constructed Empires within Empires", source: "GABlog" }], sources: [] },
  { term: "Logocentrism", slug: "logocentrism", definitionQuote: "Jacques Derrida’s concept of “logocentrism” posits that Western metaphysics presupposes that writing is a representation of speech, and therefore approximates speech in a secondary, dependent way. Speech, in logocentric terms, involves “self-presence”: the speaker is identical to his intentions, which are therefore transparent to the speaker.", definitionSource: "Logocentrism, Media, and Originary Satire", definitionSlug: "logocentrism-media-and-originary-satire", posts: 18, passages: [{ text: "If logocentrism is really phallocentrism, Eurocentrism, etc., then the critique of metaphysics is essentially volley in a partisan political battle, rather than an attempt to disclose a more originary presentation of human being than metaphysics allows.", slug: "idioms-of-inquiry-katz", title: "Another Version of \"Idioms of Inquiry\" Despite the Changed Title (Adam Katz)", source: "Essay" }, { text: "The logocentrism Derrida associated with Western metaphysical modes of thinking, along with all of its distinctions between rational and irrational, civilized and barbaric, and so on, can indeed be predicated upon modes of thinking produced by writing.", slug: "originary-grammar-and-post-sacrificial-semiotic-agency", title: "Originary Grammar and Post-Sacrificial Semiotic Agency", source: "GABlog" }, { text: "That logocentrism, that we see in concepts that construct phony simulations of battles between familiar opponents, is what is to be targeted most persistently.", slug: "media-as-scene-gablog", title: "Media as Scene", source: "GABlog" }], sources: [] },
  { term: "Love", slug: "love", definitionQuote: "Love is ceding centrality to the other. And anything named by sovereign resentment can be treated as a center, and loved accordingly. The beloved is an endless source of names.", definitionSource: "Sovereign Resentments", definitionSlug: "sovereign-resentments", posts: 120, passages: [{ text: "In other words, what converts desire into love is that the object breaks out of the vicious circle of desire by giving promise of continual mystery and by making the desirer such an object him or her self.", slug: "rendering-is-the-stay-of-frenzy-ou-ga-po", title: "Rendering is the Stay of Frenzy: Ou-GA-po", source: "GABlog" }, { text: "But our love is not the expression of an impersonal life-force.", slug: "on-love-resentment-and-the-early-chronicles", title: "On Love, Resentment and the Early Chronicles", source: "Substack" }, { text: "The movie cliché of two people looking into each others’ eyes and realizing simultaneously that they are in love is a model of this experience, which never really happens but is the presupposition of all that does.", slug: "the-terror-of-the-given", title: "The Terror of the Given", source: "GABlog" }], sources: [{ slug: "clr-121", title: "The End of Seinfeld", source: "Chronicles" }, { slug: "hunger-artistry-of-the-word", title: "Hunger Artistry of the Word", source: "GABlog" }] },
  { term: "Markets", slug: "markets", concept: "market", definitionQuote: "Markets represent forms of delegation by the central authority—markets are areas of social life that are not under direct sovereign supervision.", definitionSource: "The Generativity of the Center", definitionSlug: "anthropomorphics-the-generativity-of-the-center", posts: 75, passages: [{ text: "The market is constituted by its anxiety about its own future existence.", slug: "there-is-no-economy-pdf", title: "There Is No Economy but Only the Debt to the Center: Money, Capital and the Tributary", source: "Book" }, { text: "Markets are created by states so as to provision their militaries when abroad, and money is supplied so as to enable soldiers to participate in those markets.", slug: "anthropomorphics-center-and-distribution", title: "Center and Distribution", source: "Book" }, { text: "Markets are real insofar as they are what people without direct authority for maintaining the social center do with knowledge, information and skills when they are being protected and bounded but not directly supervised by such authorities.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }], sources: [{ slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { slug: "the-event-of-technology-gablog", title: "The Event of Technology", source: "GABlog" }, { slug: "what-are-we-talking-about-when-we-talk-about-the-market-gablog", title: "What are We Talking About When We Talk About the Market?", source: "GABlog" }] },
  { term: "Meaning", slug: "meaning", definitionQuote: "Meaning, then, is the maintenance of the field of semblances, that is, the condition where all signs are objects and all objects signs, in varying degrees and articulations. Once even something so trivial as a piece of food (where there is plenty) becomes only food and not at all a sign of some mode of sharing, meaning collapses; once even the most abstract or stylized articulation of signs can no longer be “inhabited”—converted into a set of practices—the same thing happens.", definitionSource: "The Grammar of Desire and Resentment", definitionSlug: "the-grammar-of-desire-and-resentment", posts: 307, passages: [{ text: "Meaning is ultimately grounded in ostensivity—to put it crudely, any utterance points at something, tells you what to notice.", slug: "the-meaning-of-meaning-and-metalanguage", title: "The Meaning of Meaning, and Metalanguage", source: "GABlog" }, { text: "Meaning is established rather differently in a scientific discipline organized around experimental protocols.", slug: "power-and-paradox-pdf", title: "Power and Paradox (Adam Katz)", source: "Essay" }, { text: "Of divine origin, but ultimately its meaning is rational and cognitive.", slug: "girard-on-the-passion", title: "Girard on the Passion", source: "GABlog" }], sources: [{ slug: "clr-661", title: "Communities of Meaning", source: "Chronicles" }] },
  { term: "Media", slug: "media", concept: "media", definitionQuote: "So, originary media is a network, a set of invisible lines we could hypothetically draw connecting the sensorium of each of the scene’s participants to each other’s, but also to all the different “parts” (what counts as a “part” depends on the vision, embedded in a body in motion or stasis) of all the others’ bodies.", definitionSource: "Mediated Centrality", definitionSlug: "anthropomorphics-mediated-centrality", posts: 279, passages: [{ text: "The media is already preparing the narrative of Obama the rescuer, “like” Lincoln and FDR.", slug: "barack-obama-the-greatest-president-ever", title: "Barack Obama, the Greatest President Ever!", source: "GABlog" }, { text: "The media are propaganda agencies of some power center or another—the blogger Sundance at the Conservative Treehouse asserts that the CIA leaks to the Washington Post and the FBI to the New York Times .", slug: "debts-and-deferences-gablog", title: "Debts and Deferences", source: "GABlog" }, { text: "The media is speech and writing publicized, transmitted, broadcast and preserved through technological and pedagogical—scenic—infrastructures.", slug: "media-as-infrastructural-translation", title: "Media as Infrastructural Translation", source: "Substack" }], sources: [{ slug: "media-as-scene-gablog", title: "Media as Scene", source: "GABlog" }] },
  { term: "Metalanguage", slug: "metalanguage", definitionQuote: "So, there’s no sense in which language is more real than metalanguage; and metalanguage is just as much a use of language as any other: it directs attention to uses of language, while language directs our attention to the centered world, but language is itself part of the centered world. Metalanguage is the pedagogical dimension within language, which means that the primary sin of metalanguage is assessing uses of language without issuing operable imperatives: assessments of the language use of others devoid of operable imperatives is the way I would define “cant.”", definitionSource: "On the Culling of Cant", definitionSlug: "on-the-culling-of-cant", posts: 72, passages: [{ text: "The metalanguage is the anomaly, and therefore the crisis, not its distortions.", slug: "morality-and-reference", title: "Morality and Reference", source: "GABlog" }, { text: "Metalanguage is a way of solving this problem, and it’s not surprising that the masters of writing would have found this solution to be an appropriate one to the problem of potentially infinite dissemination.", slug: "anthropomorphics-declarative-order-and-the-center", title: "Declarative Order and the Center", source: "Book" }, { text: "The most meaningful metalanguage is one that keeps attending to the distinction between language and metalanguage.", slug: "on-the-culling-of-cant", title: "On the Culling of Cant", source: "GABlog" }], sources: [{ slug: "the-meaning-of-meaning-and-metalanguage", title: "The Meaning of Meaning, and Metalanguage", source: "GABlog" }, { slug: "ap2402-2402katz", title: "Generative Anthropology as the One Big Discipline", source: "AP Journal" }] },
  { term: "Metaphysics", slug: "metaphysics", definitionQuote: "I worked with Eric Gans’s argument that metaphysics is a belief that the declarative sentence is the primary linguistic form—as I suggested, this leads to the assumption that language is essentially a mode of information transmission, rather than a means of conflict reduction, which further means that language is a means of control through asymmetrical information flows. I would now strengthen that claim as follows: metaphysics is the attempt to subordinate other elementary linguistic forms to the declarative, which means to eliminate them as independent forms.", definitionSource: "Sovereign Commands, Anarchistic Demands", definitionSlug: "sovereign-commands-anarchistic-demands-gablog", posts: 82, passages: [{ text: "Metaphysics is the attempt to rectify language when such events force language into self-reflexive states so that we can continue to look through language; originary grammar tries to articulate looking at language and with language with looking through language.", slug: "the-right-of-the-idiom-3", title: "The Right of the Idiom, 3", source: "GABlog" }, { text: "One way of breaking with Western metaphysics is by acknowledging the traditional character of all thought.", slug: "the-worlding-event", title: "The Worlding Event", source: "GABlog" }, { text: "The best-known exponent of this version of metaphysics is the German social democratic philosopher Jurgen Habermas.", slug: "sovereign-commands-anarchistic-demands-gablog", title: "Sovereign Commands, Anarchistic Demands", source: "GABlog" }], sources: [{ slug: "clr-660", title: "From Kant to GA: Four Reflections", source: "Chronicles" }] },
  { term: "Mimesis", slug: "mimesis", concept: "mimesis", definitionQuote: "My starting assumption is that humans are mimetic beings: we learn everything we learn by imitation.", definitionSource: "Bouvard on Power, Legitimacy, and Collective Projects", definitionSlug: "p-ower-reddit", posts: 65, passages: [{ text: "Mimesis is an excellent foundation for talking about the human because it provides a minimal version of human sameness that immediately opens onto a vista of human difference.", slug: "ancestries-and-meta-sovereignty", title: "Ancestries and Meta-Sovereignty", source: "GABlog" }, { text: "Mimesis is an adaptive learning behavior and as such can be considered a form of intelligence.", slug: "why-generative-anthropology", title: "Why Generative Anthropology (Peter Goldman)", source: "Essay" }, { text: "Mimesis is first of all positive and generative—you learn from watching another if you can translate what he does into your own movements.", slug: "event-intelligence", title: "Event Intelligence", source: "Substack" }], sources: [{ slug: "exhaustive-imitation", title: "Exhaustive Imitation", source: "Substack" }] },
  { term: "Mimetic Crisis", slug: "mimetic-crisis", concept: "mimesis", definitionQuote: "Gans assumes that the mimetic crisis is organized around some object of appetitive attention—most likely some food source, perhaps a recent kill.", definitionSource: "Origin and Hypothesis", definitionSlug: "anthropomorphics-origin-and-hypothesis", posts: 60, passages: [{ text: "My starting assumption is that humans are mimetic beings: we learn everything we learn by imitation.", slug: "p-ower-reddit", title: "Bouvard on Power, Legitimacy, and Collective Projects", source: "Book" }, { text: "Deferring some mimetic crisis is always the obverse of any observable act which suggests that the measure of any action is the relative imminence of that crisis and the delayed and distributed effects relative to that more or less likely crisis of the action taken.", slug: "originary-calculus", title: "Originary Calculus", source: "Substack" }, { text: "The victim does need to be consumed, and the emergent community does need to put its new sign to work to ensure this can be done in a communal and non-violent (or, sufficiently non- violent so that the mimetic crisis is not re-activated) manner.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }], sources: [] },
  { term: "Mimetic Desire", slug: "mimetic-desire", concept: "mimesis", definitionQuote: "For Girard, this mimetic desire is a source of conflict and tension within societies, and it is mitigated through the act of focusing the cumulative mimetic desires of a society on a single individual who becomes a scapegoat.", definitionSource: "Book Review: Nemesis — The Jouvenelian vs. the Liberal Model of Human Orders (Ad", definitionSlug: "nemesis-jouvenelian-liberal-model", posts: 34, passages: [{ text: "We can certainly attribute to mimetic desire the “cause” for a particular act, but mimetic desire is always mediated through language.", slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }, { text: "My starting assumption is that humans are mimetic beings: we learn everything we learn by imitation.", slug: "p-ower-reddit", title: "Bouvard on Power, Legitimacy, and Collective Projects", source: "Essay" }, { text: "Mimetic desire leads to the crisis; resentment comes in its wake, as the center now forbids us from satisfying our desire for the object located there.", slug: "sovereign-resentments", title: "Sovereign Resentments", source: "GABlog" }], sources: [] },
  { term: "Money", slug: "money", concept: "money", definitionQuote: "Money is the concrete realization of this sign of recognition; it bears a “meaning” but as opposed to the ordinary sign, it is a credit drawn on the sacred that cannot be freely reproduced.", definitionSource: "There Is No Economy but Only the Debt to the Center: Money, Capital and the Tributary", definitionSlug: "there-is-no-economy-pdf", posts: 158, passages: [{ text: "Money is used first of all for internal bureaucratic accounting in the ancient empires.", slug: "absolutist-economies-gablog", title: "Absolutist Economies", source: "GABlog" }, { text: "Money is both continuous and discontinuous with this history of exchanges with the center that constitutes humanity.", slug: "urbanomics", title: "Urbanomics", source: "GABlog" }, { text: "Money is the means by which agents compete within the networks so as to prove their usefulness to the network and to the center.", slug: "constrained-economies", title: "Constrained Economies", source: "GABlog" }], sources: [{ slug: "money-and-capital-as-media-and-power", title: "Money and Capital as Media and Power", source: "GABlog" }, { slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { slug: "debts-and-deferences-gablog", title: "Debts and Deferences", source: "GABlog" }] },
  { term: "Morality", slug: "morality", definitionQuote: "When we moralize, we want the imperatives we follow or issue to be backed by the currency of indicatives—as the imperatives in the Decalogue need the backing of \"I am the Lord thy God…\" This is because morality is a system of imperatives, and a system of imperatives requires something other than an imperative to provide articulation—indicatives embed the imperatives in a shared reality, perhaps, especially, a commanded reality.", definitionSource: "Another Version of \"Idioms of Inquiry\" Despite the Changed Title (Adam Katz)", definitionSlug: "idioms-of-inquiry-katz", posts: 118, passages: [{ text: "Teleology and morality are fully implicit in the originary structure.", slug: "the-ends-of-man", title: "The Ends of Man", source: "GABlog" }, { text: "What kind of morality is this, then—what does it consider more important than maintaining a livable social order?", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }, { text: "When we think in terms of the relation between morality and power, for example, we are conceding the differentiation of the disciplines: morality is defined in one arena (“Philosophy,” “Ethics”), and power in another (“Political Science”).", slug: "dedifferentiation", title: "Dedifferentiation", source: "GABlog" }], sources: [{ slug: "clr-551", title: "The Moral Model", source: "Chronicles" }, { slug: "mimeticism-and-morality", title: "Mimeticism and Morality", source: "GABlog" }] },
  { term: "Myth", slug: "myth", definitionQuote: "We need not share Girard’s realist etiology to accept the view that myth is an attempt to make plausible the creation of significance in an event through the projection back into the past of a model of human intentionality (“anthropomorphism”). As sign-users, we reenact the origin of the sign that defers violence. Such tales may be detached from their original ritual context.", definitionSource: "The Post-Millennial Age", definitionSlug: "clr-209", posts: 63, passages: [{ text: "This understanding of myth is not obviously related to the emergence of the Big Man, but the increasingly complexity of intentions attributed to figures on the ritual scene (which, of course, can include animals and the elements) lays the groundwork for making sense of the Big Man’s “usurpation” of the center.", slug: "the-marginal-anthropomorph", title: "The Marginal Anthropomorph", source: "GABlog" }, { text: "One (more) thing the Oedipus myth is about is human survival through love, minimally defined as the deferral of violence.", slug: "on-love-resentment-and-the-early-chronicles", title: "On Love, Resentment and the Early Chronicles", source: "Substack" }, { text: "Under a ritual order, when the interlocking imperative exchanges don’t work, myth is generated; with the evacuation of the ritual order, imperative failure leads to hypotheses (hypotheses are really articulations of particular ostensive-imperative-interrogative-declarative sequences).", slug: "data-mining-the-sentence", title: "Data Mining the Sentence", source: "Substack" }], sources: [] },
  { term: "Naming", slug: "naming", definitionQuote: "Naming is performative, like christening a ship or marrying a couple, activities that manifest the most basic social traditions. In a sense, that is what a tradition entails—a reciprocally constituting system of names.", definitionSource: "Debts and Deferences", definitionSlug: "debts-and-deferences-gablog", posts: 81, passages: [{ text: "Naming is performative, like christening a ship or marrying a couple, activities that manifest the most basic social traditions.", slug: "debts-and-deferences-gablog", title: "Debts and Deferences", source: "GABlog" }, { text: "Naming is the way the sovereign and his delegates (those who have been named by him) incorporate and authenticate institutions, authorities and practices.", slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }, { text: "Naming is also the most basic pedagogical act: nothing better marks the minimal hierarchy self-evident and modeled in any pedagogical act than saying “we’ll call this ______” Naming is the result of pedagogical practices of solicitation of the center.", slug: "anthropomorphics-the-end-of-secular-thinking", title: "The End of Secular Thinking", source: "Book" }], sources: [{ slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Narrative", slug: "narrative", concept: "narrative", definitionQuote: "Originary analysis provides a simple explanation for the failure of attempts to define the “grammar” of narrative: narrative begins not with articulated language but with the originary sign. What makes storytelling a useful paradigm for culture in general is precisely the absence of any simple correspondence between the formal structures of language and the institutional structures of narrative.", definitionSource: "Originary Narrative", definitionSlug: "ap0302-narrative", posts: 138, passages: [{ text: "Narrative is always sacrificial, regardless of the best efforts of its most sophisticated practitioners.", slug: "hypothesis-practice-vs-narrative-the-iterative-center-gablog", title: "Hypothesis/Practice Vs. Narrative: The Iterative Center", source: "GABlog" }, { text: "Narrative is originary (at least implicitly), but literature, it seems to me, is not, since it evolved later.", slug: "what-is-originary", title: "What is originary?", source: "GABlog" }, { text: "We all have a sense of how, for example, a narrative is structured—there is a hero, a goal, there are obstacles to achieving the goal, the hero overcomes them, and so on.", slug: "formalism-all-the-way-down-gablog", title: "Formalism all the way down", source: "GABlog" }], sources: [{ slug: "ap0302-narrative", title: "Originary Narrative", source: "AP Journal" }, { slug: "clr-346", title: "New Thoughts on Originary Narrative", source: "Chronicles" }] },
  { term: "Nihilism", slug: "nihilism", definitionQuote: "Nihilism is a mode of thinking that, since Nietzsche, we have been constrained to acknowledge as our own homegrown response to all transcendence, to all valuations. Nietzsche described it as the will to nothing as preferable to no will at all.", definitionSource: "Scandal, Resentment, Idolatry: The Underground Psychology of Terrorism", definitionSlug: "ap0801-resent", posts: 13, passages: [{ text: "The nihilism of much modern art and modern thought is best understood as a protest bemoaning the absence of such a world.", slug: "virality-and-sovereignty", title: "Virality and Sovereignty", source: "GABlog" }, { text: "Nihilism sets in once public battles seem to be about nothing—a combat with no real victor, because victories that are muddied, or dissipate, or are endlessly re-litigated , can no longer be appreciated as a contest.", slug: "exodus-from-the-dead-end-of-history-2", title: "Exodus from the Dead End of History, 2", source: "GABlog" }, { text: "Cynicism and nihilism can only be a local phenomenon indulged in by the privileged.", slug: "beyond-post-sacrificial", title: "Beyond “Post-Sacrificial”", source: "GABlog" }], sources: [] },
  { term: "Nominalization", slug: "nominalization", definitionQuote: "Divination is human imagination, and the way we do that now is primarily through nominalization, which creates new objects. Look at what happened above: the verbs “do” and “happen” morphed into the nouns “doings” and “happenings,” and this happened as soon as it became possible to examine the relationship between them.", definitionSource: "Technology and Magic, Doings and Happenings", definitionSlug: "technology-and-magic-doings-and-happenings", posts: 13, passages: [{ text: "A nominalization is “redeemed” in the same way, through the organization of “congregants” who can generate ostensives singularizing the nominalization.", slug: "nominalization-imperativity-and-reading-quick-or-patient", title: "Nominalization, Imperativity and Reading, Quick or Patient", source: "GABlog" }, { text: "We could construct paths to nominalization producing these concepts, which are metaphors drawn from machinery and statistics.", slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }, { text: "Even “thought” is such a nominalization of the verb “think”—we can have “thoughts,” but there is also a whole world of “thought,” with its own history.", slug: "accessing-the-ostensive-within-the-declarative", title: "Accessing the Ostensive within the Declarative", source: "GABlog" }], sources: [{ slug: "ap2402-2402katz", title: "Generative Anthropology as the One Big Discipline", source: "AP Journal" }, { slug: "nominalization-imperativity-and-reading-quick-or-patient", title: "Nominalization, Imperativity and Reading, Quick or Patient", source: "GABlog" }] },
  { term: "Occupied Center", slug: "occupied-center", concept: "the-center", definitionQuote: "One’s place in relation to the signifying center is fundamentally questionable, even if one’s relation to the occupied center is not—hence the discrepancy.", definitionSource: "Talk of the Center", definitionSlug: "anthropomorphics-talk-of-the-center", posts: 26, passages: [{ text: "The occupied center is still taken as a kind of accident, acceptable only insofar as we can reduce the occupant to the implementation of one of these concepts.", slug: "transposing-the-scene", title: "Transposing the Scene", source: "GABlog" }, { text: "The center is what makes any mutual understanding (any joint attention) possible, so disclosure is aimed at interrupting concealment of the conditions of such understanding.", slug: "a-kind-of-apocalyptic-politics", title: "A Kind of Apocalyptic Politics", source: "Book" }, { text: "The discrepancy between signifying and occupied center will generate struggles over the occupancy of the center, which struggles then inform and divide the disciplines.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }], sources: [{ slug: "way-way-after-sacral-kingship-gablog", title: "Way, Way, After Sacral Kingship", source: "GABlog" }, { slug: "form-and-paradox", title: "Form and Paradox", source: "GABlog" }, { slug: "sacral-kingship-and-after-preliminary-reflections", title: "Sacral Kingship and After: Preliminary Reflections", source: "GABlog" }] },
  { term: "Originary Event", slug: "originary-event", concept: "originary-scene", definitionQuote: "The originary scene is a transition from the animal order governed by the Alpha to a human order governed by the center.", definitionSource: "Bouvard on Originary Order Versus Liberal Individualism", definitionSlug: "ga-and-the-nap", posts: 77, passages: [{ text: "The originary event is a sample of humanity because all members of the group became sampling samples there.", slug: "the-sign-substack", title: "The Sign", source: "Substack" }, { text: "The originary event is an instance of successfully seeing what happens when we do this to that—meaning is achieved.", slug: "disciplinarity-and-the-center", title: "Disciplinarity and the Center", source: "Substack" }, { text: "The originary event is also the origin of resentment: the same sacred Being that preserves the community restrains desire while endowing the object with a sacrality that enhances its desirability.", slug: "the-anthropoetics-of-power", title: "The Anthropoetics of Power", source: "Essay" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }] },
  { term: "Originary Grammar", slug: "originary-grammar", concept: "originary-grammar", definitionQuote: "What originary grammar does to help us articulate rather than simply list the verbs in the metalanguage is ground verbs in the imperative world.", definitionSource: "First Words", definitionSlug: "first-words", posts: 58, passages: [{ text: "Anyone interested in what my originary grammar is doing at the moment, here is my latest post on JCRT Live http://jcrt.typepad.com/jcrt_live/2009/03/originary-grammar-part-2.html", slug: "originary-grammar", title: "originary grammar", source: "GABlog" }, { text: "Processing the primes through originary grammar is the path toward making language programming and making it currency, against, I would guess, the discoverers of both these linguistic hypotheses (but, maybe, we can redeem Wierzbicka’s and Gans’s intentions by prolonging them through the stacks).", slug: "stacked-presencing", title: "Stacked Presencing", source: "Substack" }, { text: "The metalanguage of literacy produces a fabricated present contrived out of various match-ups between categories deposited in the mind and categories deposited in reality—the purpose of originary grammar is to deconstruct such a present into the stacked scenes presented with the problem of succession.", slug: "techno-grammar", title: "Techno-Grammar", source: "Substack" }], sources: [{ slug: "originary-grammar-and-post-sacrificial-semiotic-agency", title: "Originary Grammar and Post-Sacrificial Semiotic Agency", source: "GABlog" }, { slug: "mistakenness-revisited-gablog", title: "Mistakenness Revisited", source: "GABlog" }] },
  { term: "Originary Hypothesis", slug: "originary-hypothesis", concept: "originary-scene", definitionQuote: "The originary hypothesis is easily summed up in a couple of paragraphs, at most, and all it really assumes is that human beings are mimetic creatures.", definitionSource: "The Originary Hypothesis in Itself", definitionSlug: "the-originary-hypothesis-in-itself", posts: 160, passages: [{ text: "The originary scene is a transition from the animal order governed by the Alpha to a human order governed by the center.", slug: "ga-and-the-nap", title: "Bouvard on Originary Order Versus Liberal Individualism", source: "Substack" }, { text: "Here, the obstacle in the way of perceiving the originary hypothesis is a refusal of paradoxical thinking.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "Does that mean that one doesn’t claim that the originary hypothesis is true, or gets us closer to the truth of human being than other ways of thinking?", slug: "mimetic-culture-liminal-culture", title: "Mimetic Culture, Liminal Culture", source: "GABlog" }], sources: [] },
  { term: "Originary Memory", slug: "originary-memory", definitionQuote: "Originary memory is taking care of language—by which I don’t mean trying to maintain it as a transparent vehicle of communication, or ensuring that words be used in their proper meaning; what I mean is that everything anyone says makes it possible to say something else that couldn’t have been said otherwise, and that in articulating one of those things that couldn’t have been said otherwise one remembers by carrying forward the very first utterance that made everything said since then possible. It is by thus heading back into the past, enriching the originary scene with everything that has happened since and therefore, in a sense, happened there, is still happening there, that we open up possible futures.", definitionSource: "Originary Memory", definitionSlug: "originary-memory", posts: 8, passages: [{ text: "Cognition as Originary Memory The shift in focus, in cognitive theory, from the relation between mind and objects in the world to the relation between minds mediated by inter-subjectivity, brings it into dialogue with originary thinking.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }, { text: "Inasmuch as originary memory reproduces a memory of the whole scene and the whole event, all forces tend toward the community’s peaceful acceptance of the new object: the usurper wishes to minimize the risk of violence to himself, and the community wishes to minimize the risk to itself.", slug: "anthropomorphics-the-center-and-the-declarative", title: "The Center and the Declarative", source: "Book" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }, { slug: "originary-memory", title: "Originary Memory", source: "GABlog" }] },
  { term: "Originary Satire", slug: "originary-satire", definitionQuote: "The representation of the temptation of transgression within the impossibilization of victimization is originary satire. We are always presenting, at different levels of explicitness and awareness, hypotheses regarding the desires and resentments informing others’ actions.", definitionSource: "Language Policy", definitionSlug: "language-policy", posts: 24, passages: [{ text: "Originary satire is clearly lashon hara, which means I have a differend to work with here.", slug: "idiom-and-the-differend", title: "Idiom and the differend", source: "Substack" }, { text: "A kind of originary satire is required here, in which one invents the gestures that display the terminal points of actions taken within the oscillation of debt issuance on the one hand, and debt enforcement on the other (roughly, the central banks and the national security/intelligence agencies).", slug: "exhaustive-imitation", title: "Exhaustive Imitation", source: "Substack" }, { text: "The originary satire which is simultaneously absolute idiomatic infiltration of central intelligence is the only sustainable mode of inscription now.", slug: "event-intelligence", title: "Event Intelligence", source: "Substack" }], sources: [{ slug: "language-policy", title: "Language Policy", source: "GABlog" }, { slug: "logocentrism-media-and-originary-satire", title: "Logocentrism, Media, and Originary Satire", source: "GABlog" }, { slug: "the-paradoxical-telos-of-the-aesthetic-gablog", title: "The Paradoxical Telos of the Aesthetic", source: "GABlog" }] },
  { term: "Originary Scene", slug: "originary-scene", concept: "originary-scene", definitionQuote: "The originary scene is a transition from the animal order governed by the Alpha to a human order governed by the center.", definitionSource: "Bouvard on Originary Order Versus Liberal Individualism", definitionSlug: "ga-and-the-nap", posts: 281, passages: [{ text: "The originary scene is commemorated in ritual, and the specific movements, arrangements and props that organize the scene through the accretion of the memories of the group in its ongoing dialogue with the center is the origin of technology.", slug: "mimesis-center-auto-immunology", title: "Mimesis, the Center and Auto-Immunology: A Review of Psychopolitical Anaphylaxis", source: "Essay" }, { text: "Following the sparagmos on the originary scene is the iteration of the scene in the ritual.", slug: "quantity", title: "Quantity", source: "GABlog" }, { text: "The paradoxes of deferral we see on the originary scene are enduring features of the human.", slug: "anthropomorphics-origin-and-hypothesis", title: "Origin and Hypothesis", source: "Book" }], sources: [] },
  { term: "Originary Sign", slug: "originary-sign", concept: "the-sign", definitionQuote: "The originary sign is iconic and ostensive, because it is constitutive—that is, it establishes the very conditions under which iconic and ostensive signs are possible; but it does so ostensively and iconically.", definitionSource: "A brief note on terminology", definitionSlug: "a-brief-note-on-terminology", posts: 38, passages: [{ text: "A sign is the deferral of violence.", slug: "language-policy", title: "Language Policy", source: "GABlog" }, { text: "The originary sign had to be gesture—it couldn’t be imagined as a sound, or a line drawn on the ground.", slug: "self-evidency", title: "Self-Evidency", source: "GABlog" }, { text: "The originary sign creates a radical difference between the meaningful central object, on the one hand, and everything else, on the other.", slug: "anthropomorphics-a-grammar-of-the-social", title: "A Grammar of the Social", source: "Book" }], sources: [] },
  { term: "Originary Thinking", slug: "originary-thinking", definitionQuote: "Ultimately, originary thinking is a way of tracing all the frames it comes across back to their origins, and through those origins, the origin of language and humanity.", definitionSource: "Within Language", definitionSlug: "within-language", posts: 84, passages: [{ text: "I don’t deny that originary thinking is also compatible with liberalism, just that it only and intrinsically is so.", slug: "the-originary-hypothesis-and-reactionary-thinking", title: "The Originary Hypothesis and Reactionary Thinking", source: "GABlog" }, { text: "Ultimately, originary thinking is a way of tracing all the frames it comes across back to their origins, and through those origins, the origin of language and humanity.", slug: "within-language", title: "Within Language", source: "GABlog" }, { text: "The task for originary thinking is explore the overlapping terrains covered by this sprawling vocabulary, and make sense of them as so many ways of being signifying beings.", slug: "selfy", title: "Selfy", source: "GABlog" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }] },
  { term: "Ostensive", slug: "ostensive", concept: "ostensive-imperative-declarative", definitionQuote: "The assumption, drawn from the originary hypothesis, that the ostensive sign is the primary linguistic form, with the imperative closely tied to the ostensive as a demand to make the indicated object present, enables us to sharpen our sense of the linguistic role of the declarative sentence.", definitionSource: "Composition Pedagogy", definitionSlug: "composition-pedagogy", posts: 218, passages: [{ text: "The ostensive is meaningless in the absence of its referent; the declarative can do without a real-world referent.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "The ostensive is the “eating” in which we find the “proof of the pudding.” This is the kind of thing a disciplinary space is interested in—what counts as a sign that an imperative has been completed?", slug: "more-on-the-proper-use-of-declarative-sentences", title: "More on the Proper Use of Declarative Sentences", source: "GABlog" }, { text: "The syntactic form that corresponds to the ostensive is, I would say, the exclamation : “what a lovely day!” expresses that originary sense of gratitude as does “how awful!” because the latter expression equally presupposes some non-awful condition that allows us all to immediately recognize how awful the one indicated is.", slug: "common-sense", title: "Common Sense", source: "GABlog" }], sources: [{ slug: "clr-537", title: "The New Origin of Language Part 3: The Ostensive", source: "Chronicles" }, { slug: "clr-539", title: "The New Origin of Language Part 4: Linguistics of the Ostensive", source: "Chronicles" }] },
  { term: "Paradox", slug: "paradox", definitionQuote: "A paradox is any sentence that puts forward a claim or rule to which it is itself the exception, but any sentence and any discourse paradoxically refers to, talks about, a world created by and therefore always running in advance of and behind the sentence or discourse itself.", definitionSource: "Paradoxicality", definitionSlug: "paradoxicality", posts: 110, passages: [{ text: "Paradox is constitutive of power and sovereignty as well, a point of supreme importance for absolutism.", slug: "power-and-paradox-gablog", title: "Power and Paradox", source: "GABlog" }, { text: "The paradox is contained within the ethical dimension as well: the deferred object becomes all the more desirable the more barred from appropriation it is.", slug: "the-sovereign-remembering-of-names", title: "The Sovereign Remembering of Names", source: "GABlog" }, { text: "Of course, this paradox is meant to examine our assumptions regarding “identity.” So, it’s still the same ship insofar as it’s still called the S.S.", slug: "crowding-out-the-political-gablog", title: "Crowding Out the Political", source: "GABlog" }], sources: [{ slug: "clr-580", title: "Paradox", source: "Chronicles" }, { slug: "clr-390", title: "The Fundamental Paradox of Signification", source: "Chronicles" }] },
  { term: "Performativity", slug: "performativity", definitionQuote: "The reliance of any utterance on the possibility of a verifying ostensive somewhere down the road is what makes language irreducibly performative (and therefore demands that performativity be made explicit and central) but the imperative amplifies and activates that performativity and makes it technological.", definitionSource: "Downstream of the Imperative", definitionSlug: "downstream-of-the-imperative", posts: 17, passages: [{ text: "The seemingly radical implication of performativity is that social roles rely upon ongoing participation and therefore revision and adaptation and can therefore always be taken up differently.", slug: "centrifugal-signifying", title: "Centrifugal Signifying", source: "Substack" }, { text: "This doesn’t mean rule by “nerds,” because linguistic performativity means leading men, and men dedicated to the most rigorous testing of the more daring hypotheses.", slug: "demand-and-the-grammar-of-desire", title: "Demand and the Grammar of Desire", source: "Substack" }, { text: "It’s easy to overlook these modes of performativity, or to examine them only in some kind of protest mode which pretends to imagine a return to an earlier form of liberty, and thereby remain focused on the predations of social media.", slug: "the-sentence-as-metric", title: "The Sentence as Metric", source: "Substack" }], sources: [{ slug: "clr-570", title: "The Originary Performative", source: "Chronicles" }] },
  { term: "Politics", slug: "politics", definitionQuote: "Politics is the establishment of an arena in which actors compete perpetually, but with distinctly marked victories and defeats determining the power to make and implement laws, before a qualified audience (qualified in the sense of allowed seats in the arena, so to speak, and in the sense of being the arbiter of victory), and without violence. The space in which politics is set is sacred, in being both commonly held and inviolable—state houses, houses of presidents, public squares, etc.", definitionSource: "The Problem and Possible Necessity of Politics", definitionSlug: "the-problem-and-possible-necessity-of-politics", posts: 287, passages: [{ text: "Politics is sure to channel such resentments, compromising the independence of independent arbiters of insurance contracts.", slug: "health-care", title: "Health Care", source: "GABlog" }, { text: "Politics is most effective when the actors represent cleavages within the audience and reflect upon the meta- or constitutive rules governing the political space itself.", slug: "the-problem-and-possible-necessity-of-politics", title: "The Problem and Possible Necessity of Politics", source: "GABlog" }, { text: "Politics is for protecting the dominion of habit and helping it become self-reflexive and open to novel compositions.", slug: "habit-and-errors-and-composition", title: "Habit and Errors and Composition (Adam Katz)", source: "Essay" }], sources: [{ slug: "from-metapolitics-to-politics", title: "From Metapolitics to Politics", source: "GABlog" }] },
  { term: "Post-Sacrificial", slug: "post-sacrificial", definitionQuote: "In a post-sacrificial order, there are no more exchanges with the gods, or even God: what God has given us is everything and incommensurable with any return; what each of us gives to God is also everything, all of us, even in the knowledge of its utter inadequacy.", definitionSource: "Can Networks Crowd Out Markets?", definitionSlug: "can-networks-crowd-out-markets-gablog", posts: 36, passages: [{ text: "The post-sacrificial epoch would better (and more positively) be called the epoch of the absolute imperative, a concept I take from Philip Rieff.", slug: "can-networks-crowd-out-markets-gablog", title: "Can Networks Crowd Out Markets?", source: "GABlog" }, { text: "Post-sacrificial civilization (accomplished via the Judaic, Biblical, and Christian revelations in the West and otherwise—via Buddhism, Taoism, Confucianism, etc., elsewhere) is the ongoing effort to bring that category into focus.", slug: "fraud-and-force", title: "Fraud and Force", source: "GABlog" }, { text: "Post-sacrificial modes of being involve giving over our desires and resentments to the center in the knowledge we will have to sustain our attention towards the center so as to be worthy of when those desires and resentments come back transformed into imperatives from the center.", slug: "total-semiotics-or-exteriorizing-the-interiors", title: "Total Semiotics, or Exteriorizing the Interiors", source: "GABlog" }], sources: [{ slug: "beyond-post-sacrificial", title: "Beyond “Post-Sacrificial”", source: "GABlog" }] },
  { term: "Power", slug: "power", concept: "power", definitionQuote: "In order to make it the point, we can begin by pointing out that power comes from the center, and the center comes from deferral. Insofar as someone occupies the center of a scene, that person wields power.", definitionSource: "Anthropomorphics: An Originary Grammar of the Center", definitionSlug: "anthropomorphics-book", posts: 550, passages: [{ text: "Power is both a priori and provisional, a location and its occupant.", slug: "power-and-paradox-gablog", title: "Power and Paradox", source: "GABlog" }, { text: "Power is ontologically prior to and causative of, markets and all the rest.", slug: "anthropomorphics-center-and-distribution", title: "Center and Distribution", source: "Book" }, { text: "Power means thwarting the ambitions of whoever would break ranks and rush to center.", slug: "the-two-charismas", title: "The Two Charismas", source: "GABlog" }], sources: [{ slug: "power", title: "Power", source: "GABlog" }, { slug: "centering", title: "Centering", source: "GABlog" }, { slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Practice", slug: "practice", definitionQuote: "A practice is something that one or some do, that can be done again and be the same thing. A practice is a doing in the middle of things that are happening. Part of the practice, then, is marking the difference between what you are doing and what is happening.", definitionSource: "Design, Imitation, and the Transfer Translation", definitionSlug: "design-imitation-and-the-transfer-translation", posts: 287, passages: [{ text: "The practice is the transposition of a sample from one field to another, in such a way that the fields are converted into elements appropriable by the practice.", slug: "truth-and-practice", title: "Truth and Practice", source: "GABlog" }, { text: "The practice is to operationalize the meanings you encounter (as, e.g., in calling something “hard” means a certain kind and degree of force would be needed to alter its surface) and elicit the stack of scenes and grammatical stack that would make the sample meaningful, or more meaningful, or put on the path toward meaning.", slug: "idioms-as-operationalized-samples", title: "Idioms as Operationalized Samples", source: "Substack" }, { text: "A practice is a doing in the middle of things that are happening.", slug: "design-imitation-and-the-transfer-translation", title: "Design, Imitation, and the Transfer Translation", source: "GABlog" }], sources: [{ slug: "truth-and-practice", title: "Truth and Practice", source: "GABlog" }, { slug: "the-imperative-constant", title: "The Imperative Constant", source: "GABlog" }, { slug: "languaging-practices", title: "Languaging Practices", source: "GABlog" }] },
  { term: "Presencing", slug: "presencing", definitionQuote: "Transcendence has us protect the separateness of the object; presencing is interested in the continuity of the scene—the object, then, would tend to devolve into a series of more or less premeditated pretexts for doing so. We keep scenes going by iterating the sign which constitutes it—there are so many ways of doing this that they couldn’t be catalogued in advance; indeed, any iteration only discovers what it is doing in the midst of doing it.", definitionSource: "Beginnings in the Middle: Presence and the Infinitesimal", definitionSlug: "beginnings-in-the-middle-presence-and-the-infinitesimal", posts: 14, passages: [{ text: "The model for this kind of semiotic presencing is sovereignty: you acknowledge that my utterance has brought into being a world you must find your way in and sustain.", slug: "absolutist-epistemology", title: "Absolutist Epistemology", source: "GABlog" }, { text: "Transcendence has us protect the separateness of the object; presencing is interested in the continuity of the scene—the object, then, would tend to devolve into a series of more or less premeditated pretexts for doing so.", slug: "beginnings-in-the-middle-presence-and-the-infinitesimal", title: "Beginnings in the Middle: Presence and the Infinitesimal", source: "GABlog" }, { text: "That’s the work of stacked presencing—to perform the stack of scenes as an ever problematic, never guaranteed prolongation of the originary scene.", slug: "stacked-presencing", title: "Stacked Presencing", source: "Substack" }], sources: [{ slug: "language-inquiry", title: "Language, Inquiry", source: "GABlog" }] },
  { term: "Rationality", slug: "rationality", definitionQuote: "The Otherness of the Trojans invades the world of the  Iliad  as an incentive to rationality, that is, the substitution of market for ritual exchange.", definitionSource: "Art and Otherness", definitionSlug: "clr-330", posts: 22, passages: [{ text: "This metaphysical ideal is actually an anarchistic ontology, because it presupposes that, as language users (involved in the exchange of declarative sentences), we are all ultimately plugged into the emergent rationality that results from the discovery that we can refine and standardize our declarative sentences so as to orient them toward the truth (i.e., logic and the dismemberment of reality into discrete parts). Anything that interferes with ascension into the rational sphere can be treated as a dysfunction or malfunction to be eliminated by the very rational means being developed, but, otherwise, all human beings are prepared, as human beings, to enter the free discursive marketplace.", slug: "sovereign-commands-anarchistic-demands-gablog", title: "Sovereign Commands, Anarchistic Demands", source: "GABlog" }, { text: "The Axial Age can be defined as a new mode of rationality transcending ritual or a kind of secularization in which new modes of universal understanding transcend narrow or “compact” social groupings, drawing upon the simultaneous emergence of Greek Philosophy, the Hebrew prophets and Asian phenomena like Buddhism and Confucianism.", slug: "the-pointman", title: "The Pointman", source: "Substack" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }] },
  { term: "Reactionary", slug: "reactionary", definitionQuote: "I think that the central theoretical difference between GA as a liberal political theory and GA as a reactionary theory is that the former sees the marketplace as decentered and the latter contends that there are always centers, to which any marketplace (or portion of a larger marketplace) is subordinate.", definitionSource: "Liberal GA, Reactionary GA", definitionSlug: "liberal-ga-reactionary-ga", posts: 62, passages: [{ text: "Reactionary politics wants the levels of adjudication all named up.", slug: "the-ministry-of-true-naming", title: "The Ministry of True Naming", source: "GABlog" }, { text: "Reactionary Future ’s explanation for the Black Lives Matter riots brings out the strengths and distinction of absolutism as a theory of social order.", slug: "the-three-resentments", title: "The Three Resentments", source: "GABlog" }, { text: "Reactionary politics derives from this approach ever more detailed maps of the power sprawl that constitutes contemporary disorder and a model of disciplined attempts at securing power.", slug: "reaction-as-political-praxis", title: "Reaction as Political Praxis", source: "GABlog" }], sources: [] },
  { term: "Reification", slug: "reification", definitionQuote: "To name is both to reify, to create a role independent of whoever fills it, and to singularize, insofar as we can always distinguish between those who more or less adequately or authoritatively “inhabit” that name. the reification is then less an alienation or objectification than the creation of a new set of capacities.", definitionSource: "Sovereign as Onomastician-in-Chief", definitionSlug: "sovereign-as-onomastician-in-chief", posts: 13, passages: [{ text: "So, nominalization, which is the linguistic and therefore more fundamental form of “reification” and “hypostatization” is a descendent of the originary sign. A nominalization is “redeemed” in the same way, through the organization of “congregants” who can generate ostensives singularizing the nominalization.", slug: "nominalization-imperativity-and-reading-quick-or-patient", title: "Nominalization, Imperativity and Reading, Quick or Patient", source: "GABlog" }], sources: [] },
  { term: "Reliability", slug: "reliability", definitionQuote: "Michael Tomasello argues that the earliest declarative sentences—utterances beyond the imperative—concerned commentary on the reliability of other individuals as potential participants in common activity. That is, the earliest “vocation” of sentences was to establish reputation and authority—the very thing needed to authorize the sentence itself.", definitionSource: "The Sovereign Remembering of Names", definitionSlug: "the-sovereign-remembering-of-names", posts: 24, passages: [{ text: "Those who take the war against the SJWs as the primary political task, then, will find it necessary to expose, systematically, the gap between nominal citizenship (and the legal and political apparatuses defining it) and real markers of civilizational reliability. It is a primary strategy of the left to exacerbate that gap, because the formal criteria for ascertaining rights can be enforced by the state in the face of markers of reliability; the counter-strategy is to expose the resulting entitlements as deliberate repudiations of even gestures of reliability.", slug: "proper-politics", title: "Proper Politics", source: "GABlog" }, { text: "We could hypothesize that in the gift economy and the honor/shame moral economy that goes along with it, it is competition among the performers, whose reliability is at stake at every instant, that is the issue; in a fully fledged market economy, it is competition among objects, and we don’t even have to see the performers.", slug: "a-little-social-theory", title: "A Little Social Theory", source: "GABlog" }, { text: "Here is where a real marker of political reliability will be one’s ability to resist the temptation to turn these accusations back on one’s accusers, which continues the transformation of politics into attempts to be licensed as an arbiter of unacceptable speech.", slug: "anthropomorphics-maintaining-the-present-of-the-center", title: "Maintaining the Present of the Center", source: "Book" }, { text: "All this would depend, of course, upon the reliability of the firm’s judgments—only insofar as those judgments and the reasoning offered for them were seen to be impartial could its success as a company and metric of civilizational layering be assured.", slug: "thirdness", title: "Thirdness", source: "Substack" }], sources: [] },
  { term: "Representation", slug: "representation", definitionQuote: "The originary hypothesis extends and revises Rene Girard’s analysis of mimetic rivalry: according to the originary hypothesis, the first sign emerged in a single event, a mimetic crisis in which the (proto) human group arrested their common and self-destructive convergence upon a common object by putting forward what Gans calls an “aborted gesture of appropriation.” Representation, then, is the deferral of violence, as is, therefore, all of culture.", definitionSource: "Anti-Semitism", definitionSlug: "anti-semitism", posts: 184, passages: [{ text: "The deferral of violence through representation is what we are “meant” to do.", slug: "the-ends-of-man", title: "The Ends of Man", source: "GABlog" }, { text: "But more importantly, no symbolic representation is involved with the alpha male’s position in the group.", slug: "a-unified-field-theory-of-victimocracy", title: "A Unified Field Theory of Victimocracy", source: "GABlog" }, { text: "Every representation does need to posit some scene upon which all “receiving” the representation are virtually present.", slug: "the-declarative-order-and-inquiry", title: "The Declarative Order and Inquiry", source: "GABlog" }], sources: [] },
  { term: "Resentment", slug: "resentment", concept: "resentment-victimary", definitionQuote: "Resentment is the emotion (?) or attitude (?) one has towards whomever denies you your desire.", definitionSource: "Hunger Artistry of the Word", definitionSlug: "hunger-artistry-of-the-word", posts: 307, passages: [{ text: "Victimary thinking is, most fundamentally, resentment towards civilization—a resentment only possible for the civilized, or those in close proximity to them.", slug: "the-offspring-of-the-progenitor-of-lies", title: "The Offspring of the Progenitor of Lies", source: "GABlog" }, { text: "Resentment is directed toward this second function of the object (or, to be a bit Lacanian, Object)—it bars the realization of desire.", slug: "the-three-resentments", title: "The Three Resentments", source: "GABlog" }, { text: "Resentment is the imitation of the central presence, the enactment of the rule that is derived from the object in the midst of the failure to clear the field for desire.", slug: "more-problems-in-the-concept-of-imitation", title: "More problems in the concept of imitation", source: "GABlog" }], sources: [{ slug: "resentment", title: "Resentment", source: "Substack" }, { slug: "praxis", title: "Praxis", source: "GABlog" }, { slug: "hunger-artistry-of-the-word", title: "Hunger Artistry of the Word", source: "GABlog" }] },
  { term: "Rights", slug: "rights", definitionQuote: "Indeed, the entire panoply of modern rights is composed of demands made upon the center, in the form of the state, to both protect citizens from each other and to restrain itself.", definitionSource: "Economism", definitionSlug: "economism", posts: 259, passages: [{ text: "We could say, instead, that rights are rooted in one’s participation in a gift economy.", slug: "the-right-of-the-idiom-continued", title: "The Right of the Idiom, continued", source: "GABlog" }, { text: "Demands for rights are deliberately destructive of meaning, because the world of meanings is what prevented attention from being lavished on the plaintiff.", slug: "the-meaning-of-meaning-and-metalanguage", title: "The Meaning of Meaning, and Metalanguage", source: "GABlog" }, { text: "In such societies, persons, property, and rights are defended by recourse to third parties, usually courts, police, and so forth, that, if necessary, wield violence on their behalf.", slug: "up-from-victimhood", title: "Up from Victimhood", source: "GABlog" }], sources: [{ slug: "ap2302-2302katz", title: "Power and Paradox", source: "AP Journal" }, { slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }] },
  { term: "Ritual", slug: "ritual", concept: "ritual", definitionQuote: "Ritual is an exchange with the center: the participant fulfills some command of the center while making a request of the center.", definitionSource: "Languaging Practices", definitionSlug: "languaging-practices", posts: 280, passages: [{ text: "Ritual is modified with the emergence of the imperative out of the ostensive.", slug: "coming-to-a-head", title: "Coming to a Head", source: "GABlog" }, { text: "Ritual is an exchange with the center: the participant fulfills some command of the center while making a request of the center.", slug: "languaging-practices", title: "Languaging Practices", source: "GABlog" }, { text: "Ritual is most fundamentally commemoration and scene-setting.", slug: "media-as-ritual", title: "Media as Ritual", source: "Substack" }], sources: [{ slug: "media-as-ritual", title: "Media as Ritual", source: "Substack" }, { slug: "languaging-practices", title: "Languaging Practices", source: "GABlog" }, { slug: "the-imperative-constant", title: "The Imperative Constant", source: "GABlog" }] },
  { term: "Sacrality", slug: "sacrality", concept: "the-sacred", definitionQuote: "The sacred is what holds our joint attention and enables us to attend to each other’s attending to.", definitionSource: "The Right of the Idiom, 2", definitionSlug: "the-right-of-the-idiom-2", posts: 73, passages: [{ text: "The underlying identity of significance and sacrality is not a mere metaphor.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "His sacrality is more abstract, and less bound up with the ebb and flow of everyday life.", slug: "power-and-paradox-pdf", title: "Power and Paradox (Adam Katz)", source: "Essay" }, { text: "In that case, the question of sacrality is suspended, because determining something to be sacred and hence the source of the good, the true, etc., would then invalidate the conversation.", slug: "secular-thinking", title: "Secular Thinking", source: "Substack" }], sources: [{ slug: "clr-531", title: "Paradox and the Sacred", source: "Chronicles" }] },
  { term: "Satire", slug: "satire", definitionQuote: "Satire is effectively total, and includes itself. Satire sees everyone as aspirants for some center who fail to see the inessentiality of that aspiration, which is to say, its roots in mimetic desire and resentment.", definitionSource: "Anthropomorphics: An Originary Grammar of the Center", definitionSlug: "anthropomorphics-book", posts: 51, passages: [{ text: "Satire is the medium in which such a winnowing out would be enacted, and for the satire to be trustworthy the ruler would have to be on the stage as well.", slug: "paradoxicality", title: "Paradoxicality", source: "GABlog" }, { text: "Satire is an attempt to further refine names until they position someone or something or some event on the originary scene, retrieved prior to the second revelation.", slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { text: "Satire is not really interested in being realistic, or in improvement—it just wants to show us what inevitably gets forgotten in more acceptable forms of representation.", slug: "esthetic-oscillations", title: "Esthetic Oscillations", source: "GABlog" }], sources: [] },
  { term: "Scapegoating", slug: "scapegoating", concept: "scapegoating", definitionQuote: "Scapegoating is also always against the center--even when the occupant of the center leads it. The claim implicit in scapegoating is that the center has been usurped by someone \"behind the scenes.\"", definitionSource: "Bouvard on Scapegoating and Egalitarian Morality", definitionSlug: "the-egalitarian-vs-hierarchical-model-of-morality", posts: 106, passages: [{ text: "Scapegoating is particularly alarming today, with the weapons of mass destruction at our disposal and the ways instantaneous media facilitate mob-like reactions to events.", slug: "speaking-your-mind-minding-your-speech", title: "Speaking Your Mind, Minding Your Speech", source: "GABlog" }, { text: "Scapegoating is a practice of subtracting likeness from the othered, making likeness among those who do the othering less threatening; to acknowledge various ways of identifying the same amongst the like is to make it possible to lower and raise the threshold of differentiation as needed.", slug: "selving", title: "Selving", source: "Substack" }, { text: "But there is some question as to whether such resistance to scapegoating is more than just “pragmatic,” with the resentment being enacted in some ritual or aesthetic manner.", slug: "fraud-and-force", title: "Fraud and Force", source: "GABlog" }], sources: [{ slug: "beyond-post-sacrificial", title: "Beyond “Post-Sacrificial”", source: "GABlog" }] },
  { term: "Scene", slug: "scene", definitionQuote: "That a scene must be organized around some mimetic crisis—actual, imminent, anticipated, simulated as a kind of rehearsal—which the sign constitutive of the scene frames and defers sharpens the question: how and when do we know when a scene has been closed and what does this knowledge consist of?", definitionSource: "Beginnings in the Middle: Presence and the Infinitesimal", definitionSlug: "beginnings-in-the-middle-presence-and-the-infinitesimal", posts: 446, passages: [{ text: "The scene is completed simply by having a “critical mass” of participants see each other this way, because enough people seeing each other this way and showing that they see each other this way is the sign.", slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { text: "The scene is fundamentally contingent for him, and the various errors in emission upon the scene are smoothed out or “normed”; nor does he have any thought as to what will come after the scene–he will participate in the sparagmos like everyone else, but he has been assimilated to the group, which can take care of itself, by that point.", slug: "habits-error-assignments", title: "Habits, Error, Assignments", source: "GABlog" }, { text: "The scene is designed so as to make that action the only conceivable one.", slug: "writing-as-technics", title: "Writing as Technics", source: "Substack" }], sources: [{ slug: "ap2202-2202matthews", title: "Anti-Hierarchical Culture in Media-Based Creative Collectives: Sketching Origina", source: "AP Journal" }, { slug: "ap2302-2302katz", title: "Power and Paradox", source: "AP Journal" }, { slug: "event-intelligence", title: "Event Intelligence", source: "Substack" }] },
  { term: "Scene of Representation", slug: "scene-of-representation", definitionQuote: "The scene of representation is the sacred space in which the new dimension of the sign originates and is shared and internalized as a cultural memory within a universally maintained history recallable by each individual as the memory of the sign. But this same space is by the same token a potential space of violence.", definitionSource: "Minimal Language", definitionSlug: "clr-472", posts: 20, passages: [{ text: "The scene of representation is still primarily a place of deferral of conflict, not contemplation of a model of reality.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "Anybody who uses language is a self endowed with free will; to use the sign on the scene of representation is to be a human self.", slug: "selfy", title: "Selfy", source: "GABlog" }, { text: "The scene of representation, however, is not just a rhetorical model of language as communication, but rather a model of transcendence or meaning.", slug: "why-generative-anthropology", title: "Why Generative Anthropology (Peter Goldman)", source: "Essay" }], sources: [{ slug: "language-inquiry", title: "Language, Inquiry", source: "GABlog" }] },
  { term: "Scenic design", slug: "scenic-design", concept: "scenic-design", definitionQuote: "Technics is the continual reinscription of the scene—scenic design practices are events within scenes that design scenes in ways that facilitate new events.", definitionSource: "Event Intelligence", definitionSlug: "event-intelligence", posts: 60, passages: [{ text: "So, the work of scenic design is the translation of events designed into narrative form into the terms of a possible practice.", slug: "scenic-design-practices-the-transfer-translation-of-events-into-scenes", title: "Scenic Design Practices: The Transfer Translation of Events into Scenes", source: "Substack" }, { text: "The purpose of scenic design is revelation: scenes should be designed so as to maximize information coming from the center, which is to say anomalies generated by the selvings across those scenes.", slug: "literature-as-para-data-and-intelligence-exchange-with-the-center", title: "Literature as Para-Data and Intelligence Exchange with the Center", source: "Substack" }, { text: "Scenic design, extracting and deriving from the scene, is the event.", slug: "programming", title: "Programming", source: "Substack" }], sources: [{ slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }] },
  { term: "Scientism", slug: "scientism", definitionQuote: "The mistake of modern scientism was to insist upon a single vocabulary to describe all of reality, which leads one to ruthlessly extirpate all other vocabularies, as they can only appear as obfuscating competitors.", definitionSource: "Language, Inquiry", definitionSlug: "language-inquiry", posts: 9, passages: [{ text: "What is ignored by this scientism is the anthropological origins of the juridical form, which lie in the suppression of the vendetta (which would mean that the discussion of appropriate punishment must always find reference to some lower threshold that might reignite the vendetta).", slug: "originary-calculus", title: "Originary Calculus", source: "Substack" }, { text: "Originary grammar should supersede scientism while preserving all the intellectual advances of science.", slug: "the-worlding-event", title: "The Worlding Event", source: "GABlog" }, { text: "“scientism,” a fellow participant in an online forum and (I think) the owner of an (eponymous) excellent twitter account, sees in the modern state a dialectic of centralization and fragmentation.", slug: "sovereignty-and-standardization", title: "Sovereignty and Standardization", source: "GABlog" }], sources: [] },
  { term: "Semantic Primes", slug: "semantic-primes", definitionQuote: "Wierzbicka has discovered a set of what she calls “Natural Semantic Primes”—that is, words, exact translations of which exist in every language. Another way of defining and testing the primes is to say they are words that can’t be paraphrased by other words, without those other words ultimately having to be paraphrased using the primes themselves.", definitionSource: "Talk of the Center", definitionSlug: "anthropomorphics-talk-of-the-center", posts: 34, passages: [{ text: "The “speech words” among the semantic primes are “say,” “words,” “true” (not even “false”).", slug: "moral-thresholds", title: "Moral Thresholds", source: "GABlog" }, { text: "The Natural Semantic Primes are on the one hand the simplest, most commonplace words and the most mysterious—how is it, exactly, that we “think,” “say,” “know,” “do” and so on?", slug: "tokenization", title: "Tokenization", source: "Substack" }, { text: "The idioms I’ve been creating out of a reduction of scenic thinking to Anna Weirzbicka’s Natural Semantic Primes is, then, intended to become the language of a team, or teams of teams, operating directly on the field of probability.", slug: "idioms-as-operationalized-samples", title: "Idioms as Operationalized Samples", source: "Substack" }], sources: [] },
  { term: "Shared Attention", slug: "shared-attention", definitionQuote: "In shared, or joint attention, is the fundamental equality that constitutes the human. All the resources we need for thinking about ethics lie in joint attention, in our ability to point to something, and approaching ethics in this way might enable use to create more minimal, more pared down, ethical vocabularies.", definitionSource: "Flipping the Conference", definitionSlug: "flipping-the-conference", posts: 46, passages: [{ text: "Indeed, the center must be marked first of all, insofar as the participants in the event attend from the sign/gesture to the object; but the effect of this shared attention is to have everyone attend from the object as sacred to each and every one’s profane desire for the object, culminating in the regulated sparagmos.", slug: "the-right-of-the-idiom-3", title: "The Right of the Idiom, 3", source: "GABlog" }, { text: "It is this first example of joint shared attention that is the beginning of human language.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "There are two ways shared attention can be interrupted: first, through some kind of distraction; second, through some kind of fixation.", slug: "flipping-the-conference", title: "Flipping the Conference", source: "GABlog" }], sources: [] },
  { term: "Sign", slug: "sign", concept: "the-sign", definitionQuote: "A sign is the deferral of violence.", definitionSource: "Language Policy", definitionSlug: "language-policy", posts: 337, passages: [{ text: "The sign is both the invention and the memory of that insight, an insight which must have been available on the scene to someone positioned so as to witness a simultaneous escalation and de-escalation in different “sectors” of the scene.", slug: "speaking-your-mind-minding-your-speech", title: "Speaking Your Mind, Minding Your Speech", source: "GABlog" }, { text: "The sign designates the central object as taboo or sacred: too desirable and dangerous to be appropriated.", slug: "why-generative-anthropology", title: "Why Generative Anthropology (Peter Goldman)", source: "Essay" }, { text: "By its nature, the sign is an individual act, even when performed with others.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }], sources: [{ slug: "clr-340", title: "Frère Jacques", source: "Chronicles" }] },
  { term: "Significance", slug: "significance", definitionQuote: "But that the first word is the name-of-God tells us that significance is not a product of disinterested contemplation, but exists to defer the violence of crisis.", definitionSource: "Free Will and Cosmological Idiocy", definitionSlug: "clr-88", posts: 80, passages: [{ text: "The ostensive offers a “profane” version of the scene, an intentional model of the universe limited to a single present reality, whose significance is presumed to require immediate attention.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "I think we could say that lowering the threshold of significance is the way we conserve linguistic presence: what threatens linguistic presence is the loss of a shared center that we could point to; by lowering the threshold of significance we place a newly identified object at that center.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }, { text: "The man of resentment suffers from his finitude, not because he knows his life is finite, but because he feels his significance is finite.", slug: "on-love-resentment-and-the-early-chronicles", title: "On Love, Resentment and the Early Chronicles", source: "Substack" }], sources: [{ slug: "clr-536", title: "The New Origin of Language Part 2: Formal and Institutional Representation", source: "Chronicles" }] },
  { term: "Signification", slug: "signification", definitionQuote: "Signification is not a mechanism ; its functioning depends on the fact that each use of a “symbolic” sign reactivates, with vastly diminished affect, the originary sacred context. This context is, however little we are conscious of it, a collective one; the sign is a mode of communication whose reduction to a solipsistic recording of thought distorts its function beyond repair. In the originary event, the movement of appropriative intent toward the object becomes a signifying gesture representing the object.", definitionSource: "Return of the Sacred I – The Sacred and the Significant", definitionSlug: "clr-326", posts: 28, passages: [{ text: "In contrast, the signification-criterion is roughly speaking that of truth, al though only declarative sentences possess a genuine truth-value.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "Attending to the tacit knowing enabling any signification recuperates distractions by using them to break up the fixations that interfere with our attending to the overlapping margins of our idioms that make language learning possible.", slug: "flipping-the-conference", title: "Flipping the Conference", source: "GABlog" }, { text: "Any act of signification aims at changing the field of probabilities within which it is situated.", slug: "idioms-as-operationalized-samples", title: "Idioms as Operationalized Samples", source: "Substack" }], sources: [{ slug: "clr-536", title: "The New Origin of Language Part 2: Formal and Institutional Representation", source: "Chronicles" }, { slug: "clr-537", title: "The New Origin of Language Part 3: The Ostensive", source: "Chronicles" }] },
  { term: "Signifying Center", slug: "signifying-center", concept: "the-center", definitionQuote: "So, the \"signifying center\" is the meaning with which we imbue the occupied center and all its branches.", definitionSource: "Bouvard on Center, Collective Intentionality, and Power", definitionSlug: "adam-katz-how-do-you-define-the-concept-of-the-center", posts: 24, passages: [{ text: "The center is what makes any mutual understanding (any joint attention) possible, so disclosure is aimed at interrupting concealment of the conditions of such understanding.", slug: "a-kind-of-apocalyptic-politics", title: "A Kind of Apocalyptic Politics", source: "GABlog" }, { text: "One’s place in relation to the signifying center is fundamentally questionable, even if one’s relation to the occupied center is not—hence the discrepancy.", slug: "anthropomorphics-talk-of-the-center", title: "Talk of the Center", source: "Book" }, { text: "Through these pedagogical and moral practices the signifying center is brought to bear on the occupied center, and imperative gap closed.", slug: "anthropomorphics-the-center-and-imperative-authority", title: "The Center and Imperative Authority", source: "Book" }, { text: "The signifying center, which under sacral conditions was supplemented by narrative and liturgical knowledge on the part of supplicants, is now constituted by attempts to apply remembered promises from the occupied center to the very scenic (technological) conditions constructing the memory.", slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }], sources: [{ slug: "from-metapolitics-to-politics", title: "From Metapolitics to Politics", source: "GABlog" }, { slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }, { slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }] },
  { term: "Signing", slug: "signing", definitionQuote: "Verification of the “truth” of the ostensive sign is inherent in the signing act itself; to emit a linguistic or “symbolic” sign is ipso facto not to appropriate its referent, and the sign’s prolongation contains within it an implicit promise of continued non-appropriation.", definitionSource: "Frère Jacques", definitionSlug: "clr-340", posts: 10, passages: [{ text: "It’s starting to look like fewer men are signing up—how many would be enough to make a difference?", slug: "system-s-theory", title: "System’s Theory", source: "GABlog" }, { text: "But now that GA has provided the birth of our signing ability with a plausible real-world foundation, the problems of both philosophy and the human sciences can be placed on a new footing.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "The token issuing institution might then be signing onto the charters issued by the center, committing to issuing a certain line of credit.", slug: "ve-ortexicality-post-axial-age-morality", title: "Ve/ortexicality: Post-Axial Age Morality", source: "Substack" }], sources: [] },
  { term: "Sociality", slug: "sociality", definitionQuote: "The complementary problems of succession (the continuity of the center, the system of references of the occupied to the signifying center) and of meaning (enhancing the scenic performativity of our signs), which is all that sociality is comprised of, find their solutions in the creation of such spaces.", definitionSource: "Generating Idiomatic Intelligences and Translation Practices", definitionSlug: "generating-idiomatic-intelligences-and-translation-practices", posts: 26, passages: [{ text: "The line between anti-sociality and more formalized sociality is drawn through language itself.", slug: "anthropomorphics-the-center-speaking", title: "The Center, Speaking", source: "Book" }, { text: "Directly representing our sociality is paradoxical, then, because any such representation now becomes the property of our language, requiring new representations.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }, { text: "The complementary problems of succession (the continuity of the center, the system of references of the occupied to the signifying center) and of meaning (enhancing the scenic performativity of our signs), which is all that sociality is comprised of, find their solutions in the creation of such spaces.", slug: "generating-idiomatic-intelligences-and-translation-practices", title: "Generating Idiomatic Intelligences and Translation Practices", source: "Substack" }], sources: [] },
  { term: "Sovereign Imaginary", slug: "sovereign-imaginary", definitionQuote: "A while back I formulated the concept of the “sovereign imaginary.” This concept represents the assumption anyone makes who expresses a desire or some resentment, who says “we should…” or “someone should…,” regarding some authority who could do the thing “we should” do. If you say “Medicare for all,” you imply a model of a state that would implement Medicare for all and would do so in the way you intend.", definitionSource: "The Central Imaginary", definitionSlug: "the-central-imaginary-gablog", posts: 10, passages: [{ text: "A sovereign imaginary implies a staffing of the officer class.", slug: "on-the-use-of-the-center-margin-model-to-displace-the-left-right-model", title: "On the Use of the Center-Margin Model to Displace the Left-Right Model", source: "GABlog" }, { text: "To the liberal presupposing an anarchist sovereign imaginary we counter-presuppose sovereign naming.", slug: "semiotic-engineering-gablog", title: "Semiotic Engineering", source: "GABlog" }, { text: "Even a globalist, even an anarchist, inhabits a sovereign imaginary, whether it be international human rights courts and organizations mediating trade disputes, on the one hand, or spontaneously formed agreements between unbound individuals, on the other hand.", slug: "the-central-imaginary-gablog", title: "The Central Imaginary", source: "GABlog" }], sources: [{ slug: "the-central-imaginary-gablog", title: "The Central Imaginary", source: "GABlog" }] },
  { term: "Sovereignty", slug: "sovereignty", concept: "sovereignty", definitionQuote: "But it seems that a time will come when the second option is chosen, and the ruler, whether the traditionally anointed one or his usurper, will have to assert sovereignty, a new mode of centrality that claims and enforces the right to be the judge of last resort in all disputes involving lower centers of power.", definitionSource: "Centrality, Power, Sovereignty", definitionSlug: "centrality-power-sovereignty", posts: 197, passages: [{ text: "Sovereignty is the defense of the line qualifying the actors and audience.", slug: "the-problem-and-possible-necessity-of-politics", title: "The Problem and Possible Necessity of Politics", source: "GABlog" }, { text: "Sovereignty is the central issue here, more explicitly than it has ever been.", slug: "saturating-sovereignty", title: "Saturating Sovereignty", source: "GABlog" }, { text: "Sovereignty is always passed off—to be sovereign is to decide upon one’s successor.", slug: "securing-sovereignty", title: "Securing Sovereignty", source: "GABlog" }], sources: [{ slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }, { slug: "the-bearer-of-sovereignty", title: "The Bearer of Sovereignty", source: "Substack" }] },
  { term: "Sparagmos", slug: "sparagmos", concept: "sparagmos", definitionQuote: "Gans hypothesizes a “sparagmos,” a violent tearing apart of the central object driven by resentment at the object for “refusing” itself, however momentarily, to the group’s appetite.", definitionSource: "The Generativity of Deferral", definitionSlug: "the-generativity-of-deferral", posts: 32, passages: [{ text: "In this case, the participants in the sparagmos are essentially summarizing the scene to each other.", slug: "language-inquiry", title: "Language, Inquiry", source: "GABlog" }, { text: "So it’s delayed—but if the sparagmos is, in fact the central being giving itself up, wouldn’t that “appease” rather than exacerbate any resentment?", slug: "hunger-artistry-of-the-word", title: "Hunger Artistry of the Word", source: "GABlog" }, { text: "Subsequent to the sparagmos is a repetition or replay of the originary scene making use of the remains of the devoured object—this is the origin of ritual.", slug: "the-generativity-of-deferral", title: "The Generativity of Deferral", source: "GABlog" }], sources: [{ slug: "ap1601-1601katz", title: "Originary Mistakenness, Defilement and Modernity", source: "AP Journal" }] },
  { term: "Teaching", slug: "teaching", definitionQuote: "Teaching is always a gift to a stranger, even if the teacher and student are close friends, because we are meeting on a yet to be generated scene of joint attention, and on that scene we will become different from what we are. Learning is to incur a debt that can only be paid forward, to other strangers, even if one of those strangers is the teacher himself.", definitionSource: "Economism", definitionSlug: "economism", posts: 59, passages: [{ text: "Teaching is always a gift to a stranger, even if the teacher and student are close friends, because we are meeting on a yet to be generated scene of joint attention, and on that scene we will become different from what we are.", slug: "economism", title: "Economism", source: "GABlog" }, { text: "To think technologically about teaching is to think in terms of the various ways of \"downloading\" models.", slug: "double-helix-v9-teaching-machines-review", title: "Book Review: Teaching Machines — Audrey Watters (Adam Katz)", source: "Essay" }, { text: "In this case, I’m also learning (a teacher who doesn’t learn things in teaching is a bad teacher).", slug: "nominalization-imperativity-and-reading-quick-or-patient", title: "Nominalization, Imperativity and Reading, Quick or Patient", source: "GABlog" }], sources: [{ slug: "mimeticism-and-morality", title: "Mimeticism and Morality", source: "GABlog" }, { slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Technics", slug: "technics", concept: "technology", definitionQuote: "How do we solve problems, especially technical problems—but that means all problems, because technics is nothing more than the construction, maintenance, and modification of the scenes upon which we act.", definitionSource: "Figuring Things Out", definitionSlug: "figuring-things-out", posts: 35, passages: [{ text: "Technics is the continual reinscription of the scene—scenic design practices are events within scenes that design scenes in ways that facilitate new events.", slug: "event-intelligence", title: "Event Intelligence", source: "Substack" }, { text: "Indeed, technology is the dominant form of power. If technology presents itself to us as an enormous system of interlocking imperatives which provides a very precise slot for us to insert our own imperatives, who or what is at the center? What ostensive sign generates the system of imperatives? Technology is completely bound up with the specific forms the centralization of power takes in the wake of the desacralization of power.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Substack" }, { text: "Technics, that is, serves the originary media of the scene—everyone positioned in a particular way in relation to the center so as to re-enact the originary scene.", slug: "mimological-impressments", title: "Mimological Impressments", source: "Substack" }], sources: [{ slug: "mimological-impressments", title: "Mimological Impressments", source: "Substack" }, { slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }] },
  { term: "Technology", slug: "technology", concept: "technology", definitionQuote: "Indeed, technology is the dominant form of power. If technology presents itself to us as an enormous system of interlocking imperatives which provides a very precise slot for us to insert our own imperatives, who or what is at the center? What ostensive sign generates the system of imperatives? Technology is completely bound up with the specific forms the centralization of power takes in the wake of the desacralization of power.", definitionSource: "Anthropomorphics: An Originary Grammar of the Center", definitionSlug: "anthropomorphics-book", posts: 158, passages: [{ text: "Technology is imperative—what we become capable of doing becomes what we have no choice but to do.", slug: "back-to-nature", title: "Back to Nature", source: "GABlog" }, { text: "Technology is completely bound up with the specific forms the centralization of power takes in the wake of the desacralization of power.", slug: "the-event-of-technology-gablog", title: "The Event of Technology", source: "GABlog" }, { text: "Technology is at least potentially solid and enduring—we can tell how long built things will last—but finance is exactly the opposite.", slug: "credit-idiom-imperative-perfection-expectant-scenes", title: "Credit-Idiom-Imperative Perfection: Expectant Scenes", source: "Substack" }], sources: [{ slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }] },
  { term: "The Big Scene", slug: "the-big-scene", definitionQuote: "The Big Scene is big in size and in consequences, but most importantly it is big in the sense of limitless because it is a scene constructed, not around a center, but in order to prevent the emergence of a center.", definitionSource: "The Big Scene is the Anthropological Basis of Anarchist Ontology", definitionSlug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", posts: 15, passages: [{ text: "The Big Scene is big in size and in consequences, but most importantly it is big in the sense of limitless because it is a scene constructed, not around a center, but in order to prevent the emergence of a center.", slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }, { text: "I’ll be coming back here to issues addressed in a post from April 9, 2019, “The Big Scene is the Anthropological Basis of Anarchist Ontology,” and which I can now place in the context of the conversion of the ritual/mythical nexus into practices.", slug: "transposing-the-scene", title: "Transposing the Scene", source: "GABlog" }, { text: "On the Big Scene we will never be done with money, capital, debt, exemplary victims and the apocalyptic struggle against tyranny.", slug: "scenic-design-practices-the-transfer-translation-of-events-into-scenes", title: "Scenic Design Practices: The Transfer Translation of Events into Scenes", source: "Substack" }], sources: [{ slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }, { slug: "mistakenness-revisited-gablog", title: "Mistakenness Revisited", source: "GABlog" }, { slug: "scenic-design-practices-the-transfer-translation-of-events-into-scenes", title: "Scenic Design Practices: The Transfer Translation of Events into Scenes", source: "Substack" }] },
  { term: "The West", slug: "the-west", definitionQuote: "I reduce “the West” to a simple observation or definition: the West is where the problem of “tyranny” is a perpetual concern. Is there even a concept like “dictator” in any other civilization?", definitionSource: "Rotating Dictatorship", definitionSlug: "rotating-dictatorship", posts: 80, passages: [{ text: "The West is the inheritor of the Big Man revolution—as for why this should be the case, well, here we can welcome all those intellectual, political and even genetic genealogies of the West.", slug: "rotating-dictatorship", title: "Rotating Dictatorship", source: "Substack" }, { text: "Perhaps the main export of the West is our music, movies, and television shows.", slug: "towards-a-globalist-victimary-unified-field-theory", title: "Towards a Globalist-Victimary Unified Field Theory", source: "GABlog" }, { text: "To a great extent the pre-modern history of the West is a series of attempts to make sense of the sovereign’s accountability to God.", slug: "the-attentional-structure-of-sovereignty", title: "The Attentional Structure of Sovereignty", source: "GABlog" }], sources: [] },
  { term: "Thinking", slug: "thinking", definitionQuote: "So, to get started, thinking is obeying the imperative to suspend all imperatives: in this suspension, imperatives approach or occur to one, appearing as possibilities which the thinker in his/her detachment follows; ultimately, the emergence of one imperative after another leads us to the founding imperative of thought, to cease obeying commands directing us to efface the ostensive sign.", definitionSource: "Idioms of Inquiry", definitionSlug: "idioms-of-inquiry", posts: 522, passages: [{ text: "A model of thinking is always a model of a disciplinary space.", slug: "the-single-source-of-moral-and-intellectual-innovation-gablog", title: "The Single Source of Moral and Intellectual Innovation", source: "GABlog" }, { text: "I don’t deny that originary thinking is also compatible with liberalism, just that it only and intrinsically is so.", slug: "the-originary-hypothesis-and-reactionary-thinking", title: "The Originary Hypothesis and Reactionary Thinking", source: "GABlog" }, { text: "The problem of political thinking is to scale up the self-discipline we practice so as to exercise sovereignty where we can.", slug: "anthropomorphics-and-reaction", title: "Anthropomorphics and Reaction", source: "GABlog" }], sources: [{ slug: "ap1302-1302gans", title: "Generative Anthropology – A New Way of Thinking?", source: "AP Journal" }] },
  { term: "Thirdness", slug: "thirdness", definitionQuote: "Thirdness is the recipient and normalization of the interplay of firstness and secondness, founding and institutionalization, but it is also the position of the witness or spectator. The ability to detach yourself sufficiently from ongoing events so as to observe them as an unfolding drama is an originary source of thinking, morality and esthetics.", definitionSource: "The Single Source of Moral and Intellectual Innovation", definitionSlug: "the-single-source-of-moral-and-intellectual-innovation-gablog", posts: 22, passages: [{ text: "Thirdness is the recipient and normalization of the interplay of firstness and secondness, founding and institutionalization, but it is also the position of the witness or spectator.", slug: "the-single-source-of-moral-and-intellectual-innovation-gablog", title: "The Single Source of Moral and Intellectual Innovation", source: "GABlog" }, { text: "Thirdness is intended to be such a mode of organizing and strategizing.", slug: "the-tokenization-of-resentment", title: "The Tokenization of Resentment", source: "Substack" }, { text: "Thirdness is to be designed so as simulate this process of transformation so closely as to eventually become it.", slug: "modeling-thirdness-2", title: "Modeling Thirdness 2", source: "Substack" }], sources: [{ slug: "mimetic-theory-and-high-low-v-the-middle", title: "Mimetic Theory and High-Low v the Middle", source: "GABlog" }] },
  { term: "Threshold of Significance", slug: "threshold-of-significance", definitionQuote: "I think we could say that lowering the threshold of significance is the way we conserve linguistic presence: what threatens linguistic presence is the loss of a shared center that we could point to; by lowering the threshold of significance we place a newly identified object at that center. So, right away we can talk about “thinking” or “cognition” as the discipline of conserving linguistic presence by lowering the threshold of significance.", definitionSource: "Cognition as Originary Memory", definitionSlug: "cognition-as-originary-memory", posts: 26, passages: [{ text: "I think we could say that lowering the threshold of significance is the way we conserve linguistic presence: what threatens linguistic presence is the loss of a shared center that we could point to; by lowering the threshold of significance we place a newly identified object at that center.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }, { text: "All practices tend towards lowering the threshold of significance.", slug: "transposing-the-scene", title: "Transposing the Scene", source: "GABlog" }, { text: "This means inventing practices that lower the threshold of significance.", slug: "the-single-source-of-moral-and-intellectual-innovation-gablog", title: "The Single Source of Moral and Intellectual Innovation", source: "GABlog" }], sources: [] },
  { term: "Truth", slug: "truth", definitionQuote: "You speak your mind in order, to refer to the Eastern European dissidents like Vaclev Havel, to “live in truth,” and, as I said before, the truth is on the borderline where scapegoating is as difficult to resist as it is to carry out, with the emphasis on “live” suggesting that it’s better to make the scapegoating ever so slightly the more difficult .", definitionSource: "Speaking Your Mind, Minding Your Speech", definitionSlug: "speaking-your-mind-minding-your-speech", posts: 181, passages: [{ text: "The truth is, you can’t argue about abuses of the civil rights legal and political inheritance without being forced to disentangle what from that inheritance is worthy of preservation.", slug: "fighting-pc", title: "Fighting PC", source: "GABlog" }, { text: "The truth is that, strictly speaking, desire cannot coincide with meaning: the purer the desire, the more any interference with that desire must be destroyed, intellectually and physically, if possible.", slug: "the-grammar-of-desire-and-resentment", title: "The Grammar of Desire and Resentment", source: "GABlog" }, { text: "The truth is that the anti-white dimension of the globalist/leftist juggernaut goes far deeper than any “welfare state,” “regulatory,” or “meritocratic” issues can get at, and requires for its intellectual dismantling a more sophisticated hermeneutics that relies upon in-group tacit agreement.", slug: "the-prospects-of-sovereignty", title: "The Prospects of Sovereignty", source: "GABlog" }], sources: [{ slug: "truth", title: "Truth", source: "GABlog" }, { slug: "absolutist-epistemology", title: "Absolutist Epistemology", source: "GABlog" }, { slug: "truth-and-practice", title: "Truth and Practice", source: "GABlog" }] },
  { term: "Tyranny", slug: "tyranny", definitionQuote: "Tyranny is the manifestation of and response to greed and the desire for domination, “passions” liberated on the post-sacral market.", definitionSource: "Metalanguage and Metapolitics", definitionSlug: "anthropomorphics-metalanguage-and-metapolitics", posts: 60, passages: [{ text: "Tyranny is the manifestation of and response to greed and the desire for domination, “passions” liberated on the post-sacral market.", slug: "anthropomorphics-metalanguage-and-metapolitics", title: "Metalanguage and Metapolitics", source: "Book" }, { text: "This is the only way to fully recoup the Big Man revolution (against the Left, which is really primarily, ferociously, primordially, opposed to precisely this) and “solve” the problem of tyranny is through the establishment of a rotating dictator system.", slug: "rotating-dictatorship", title: "Rotating Dictatorship", source: "Substack" }, { text: "Politics can be distinguished from rule, or tyranny, by the competitive nature of the struggle and the actor-audience relation.", slug: "the-problem-and-possible-necessity-of-politics", title: "The Problem and Possible Necessity of Politics", source: "GABlog" }], sources: [] },
  { term: "Universalism", slug: "universalism", definitionQuote: "Universalism is really the imagining of the world under a single empire—not necessarily under the rule of a single individual or institution (but maybe that as well), but certainly all subject to the same regime of rights and their enforcement. To contend for universalism is to make war on the particulars—that is, everyone less universal than you take yourself to be.", definitionSource: "Nationalism, Globalism, Empire", definitionSlug: "nationalism-globalism-empire", posts: 11, passages: [{ text: "Universalism is the fantasy that all humans are occupying the same disciplinary space.", slug: "formalism-all-the-way-down-gablog", title: "Formalism all the way down", source: "GABlog" }, { text: "Universalism is really the imagining of the world under a single empire—not necessarily under the rule of a single individual or institution (but maybe that as well), but certainly all subject to the same regime of rights and their enforcement.", slug: "nationalism-globalism-empire", title: "Nationalism, Globalism, Empire", source: "GABlog" }, { text: "In universalism, the individual is imagined as potential victim of overweening power, and the solution is for that individual to be ever further abstracted so as to be acted upon by an even overweenier power.", slug: "absolutism-the-axial-age-and-the-laboratory", title: "Absolutism, the Axial Age and the Laboratory", source: "GABlog" }], sources: [{ slug: "formalism-all-the-way-down-gablog", title: "Formalism all the way down", source: "GABlog" }] },
  { term: "Victimary Thinking", slug: "victimary-thinking", concept: "resentment-victimary", definitionQuote: "Victimary thinking is, most fundamentally, resentment towards civilization—a resentment only possible for the civilized, or those in close proximity to them.", definitionSource: "The Offspring of the Progenitor of Lies", definitionSlug: "the-offspring-of-the-progenitor-of-lies", posts: 38, passages: [{ text: "Victimary thinking is, most fundamentally, resentment towards civilization—a resentment only possible for the civilized, or those in close proximity to them.", slug: "the-offspring-of-the-progenitor-of-lies", title: "The Offspring of the Progenitor of Lies", source: "GABlog" }, { text: "Victimary thinking is an ugly and dangerous business, but the inhabitants of advanced economies in their “crowd-sourced” wisdom appear to have determined so far that it is the lesser evil compared to naked hierarchy.", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }, { text: "Victimary thinking is, for Gans, a moral transformation in Western society resulting from the shock at the Nazi genocide of the Jews.", slug: "the-anthropoetics-of-power", title: "The Anthropoetics of Power", source: "Essay" }], sources: [{ slug: "clr-230", title: "Victimary Thinking Forever?", source: "Chronicles" }, { slug: "clr-538", title: "Victimary Passion", source: "Chronicles" }, { slug: "clr-499", title: "Firstness and Victimary Religion", source: "Chronicles" }] },
  { term: "Wisdom", slug: "wisdom", definitionQuote: "Wisdom, we can say, is the bringing to bear of the paradoxical nature of human existence as a means of deferral of sacrifice.", definitionSource: "The Center, its Affordances and Issuances, and Time.", definitionSlug: "the-center-its-affordances-and-issuances-and-time", posts: 42, passages: [{ text: "What we should dare to call the beginning of wisdom is the realization that at the origin, significant and sacred are synonymous.", slug: "clr-585", title: "Generative Theology", source: "Substack" }, { text: "The new urbanity might be historical wisdom, and it might provide a model for leaving off defense of civilized standards.", slug: "the-rhythm-of-civilization", title: "The Rhythm of Civilization", source: "GABlog" }, { text: "We have the “crowd-sourced” wisdom of the inhabitants, but then the “transnational elite” and its hierarchy makes an immediate entrance.", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }], sources: [] },
];
